WowPlusGuidePlaces = {
  [33] = { name = "Shadowfang Keep", raid = false, levels = {18,21,16}, picture = "SHADOWFANGKEEP", where = {"Silverpine Forest",44.6,67.7}, quests = {{22,"The Baron's Household","A","Archmage Malin","Stormwind City","Lay Baron Silverlaine and Commander Springvale to rest in Shadowfang Keep, in Silverpine Forest, then return to Archmage Malin in the Mage Quarter of Stormwind.",9200049},{23,"Dalaran's Mistake","A","Archmage Malin","Stormwind City","Kill Archmage Arugal at the top of Shadowfang Keep, then return to Archmage Malin in the Mage Quarter of Stormwind.",9200050},{25,"Deathstalkers in Shadowfang","H","High Executor Hadrec","Silverpine Forest","Find the Deathstalker Adamant and Deathstalker Vincent.",1098},{25,"The Orb of Soran'ruk","","Doan Karhan","The Barrens","Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",1740},{26,"The Book of Ur","H","Keeper Bel'dugur","Undercity","Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",1013},{27,"Arugal Must Die","H","Dalar Dawnweaver","Silverpine Forest","Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",1014}}, stories = {["archmage arugal"]="Arugal was a mage of Dalaran who sat among the Kirin Tor and carried the title of archmage. Dalar Dawnweaver, a Kirin Tor mage who has since risen among the Forsaken, remembers him as a charlatan whose spellcraft was so transparent that he was not fit to clean chamber pots in Dalaran, and says he propped up his weak magic with enchanted items.\n\nWhen the Scourge came, Arugal released the worgen to help the Kirin Tor mages of Dalaran against the undead. The beasts slipped his control and began to spread their curse. They overran Baron Silverlaine's keep above Pyrewood Village and killed the baron, and Arugal, mad with guilt, took the worgen as his children and renamed the place Shadowfang Keep.\n\nFrom there he spread the curse through Silverpine, to the Moonrage and Shadowfang packs and the people of Pyrewood. The Kirin Tor sent Sorcerer Ashcrombe to check on his work against the undead, and the Forsaken now want his head. In his study he still keeps a book by Ur, a Dalaran mage who studied other worlds.",["baron silverlaine"]="Baron Silverlaine was the lord of the keep that looks down on Pyrewood Village. It was called Silverlaine Keep then, and the baron lived there with his household and his soldiers until Archmage Arugal's worgen overran the walls and killed him.\n\nDeath did not release him. His cursed ghost still walks the dining room, attended by some of his servants, and he meets every stranger who enters his home as a trespasser who must be punished.",["commander springvale"]="Commander Springvale was a paladin of the Silver Hand and the commander of the soldiers who served Baron Silverlaine. When the worgen overran Shadowfang Keep he fell with the men under his command.\n\nHis ghost haunts the council room, where he is still surrounded by his soldiers. Death has not ended his loyalty, and he keeps the room against everyone who comes in, for the sake of the lord he served.",["fenrus the devourer"]="Fenrus is the pet of Archmage Arugal, a worg of unbelievable size that prowls the main study of Arugal's chambers. He may have been shaped by dark magic, whether from Arugal himself or from the worgen who serve him.\n\nWhenever Fenrus senses an intruder he lets out a thundering roar that can be heard from every corner of the keep.",["odo the blindwatcher"]="Odo the Blindwatcher is a worgen of Arugal's Shadowfang pack. He lives in the rickety wooden structure that hangs off the side of the keep, and he shares it with two pet bats, a Blood Seeker and a Vile Bat.\n\nHe lost his sight long ago, which is how he got his name. Over the years he learned to rely on his other senses, as his bats do.",["razorclaw the butcher"]="Razorclaw the Butcher lairs in what was once the kitchen of Shadowfang Keep. When his master, Arugal, brought him into the keep, he slaughtered many innocent humans there. The name he carries comes from that butchery.",["rethilgore"]="Rethilgore, known as the Cell Keeper, is one of the most vicious worgen in Archmage Arugal's pack. Arugal trusted him to guard the prisoners taken inside Shadowfang Keep.\n\nTwo of them are Deathstalker Adamant, a Forsaken scout whom High Executor Hadrec sent to learn what he could about the keep, and Sorcerer Ashcrombe, who came on behalf of the Kirin Tor. Adamant was caught by one of Arugal's magical wards and thrown into a cell, with Rethilgore standing over it.",["wolf master nandos"]="Wolf Master Nandos is the worgen master of the lesser worgs in Arugal's service. He keeps a pack of his own, and its members fall on intruders before they can reach him.\n\nHe is the last of Arugal's henchmen to block the way to the archmage."} },
  [34] = { name = "Stormwind Stockade", raid = false, levels = {22,25,20}, picture = "STORMWINDSTOCKADES", where = {"Stormwind City",50.3,66.1}, quests = {{25,"What Comes Around...","A","Guard Berton","Redridge Mountains","Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",386},{26,"A Blackrock's Debt","H","Eitrigg","Orgrimmar","Kill Targorr the Dread in the Stockade, beneath Stormwind, then return to Eitrigg in Grommash Hold in Orgrimmar.",9200070},{26,"Crime and Punishment","A","Councilman Millstipe","Duskwood","Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",377},{26,"Quell The Uprising","A","Warden Thelwater","Stormwind City","Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.",387},{26,"The Color of Blood","A","Nikova Raskol","Stormwind City","Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.",388},{27,"The Fury Runs Deep","A","Motley Garmason","Wetlands","Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.",378},{27,"The Mason's Lieutenant","H","Sage Truthseeker","Thunder Bluff","Kill Bazil Thredd in the Stockade, beneath Stormwind, then return to Sage Truthseeker on the Elder Rise in Thunder Bluff.",9200071},{29,"The Stockade Riots","A","Warden Thelwater","Stormwind City","Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.",391}}, stories = {["bazil thredd"]="Bazil Thredd was Edwin VanCleef's second-in-command and most trusted lieutenant in the Defias Brotherhood. He was captured and put in the Stormwind Stockade. For many months he had no visitors, and his jailers took it that the Brotherhood had written him off.\n\nThen, a few months before the Stockade riots, a man calling himself Maelik began to visit him. Maelik carried messages between Thredd, VanCleef and Lord Gregor Lescovar of the House of Nobles, and Thredd and Lescovar planned an uprising in the Stockade. Now Thredd leads the Defias among the prisoners, and Warden Thelwater wants his head.",["dextren ward"]="Dextren Ward came from Duskwood, where he was caught selling corpses from the Raven Hill Cemetery to the necromancer Morbent Fel. Lord Ello Ebonlocke and the Darkshire council sentenced him to death. The House of Nobles in Stormwind claimed the prisoner for itself and locked him in the Stockade instead of letting the sentence be carried out.\n\nThe people of Darkshire took that as an insult. Councilman Millstipe wants Ward's hand as proof that justice was done and says the nobles ignore Duskwood's needs. In the riot that followed, he is counted among the instigators.",["hamhock"]="Hamhock is a two-headed ogre held in the Stormwind Stockade. When the prisoners rose against their guards he joined the ringleaders of the riot, and he now watches over the chamber of three cells where Bazil Thredd sits in the middle one.",["kam deepfury"]="Kam Deepfury is a Dark Iron dwarf, and Alliance intelligence at Dun Modr names him as the planner of the attack on the Thandol Span. The blast destroyed one of the two great bridges that join the Wetlands to the Arathi Highlands, and many dwarves died, among them the brother of Longbraid the Grim.\n\nStormwind holds him in the Stockade for political reasons and has not put him to death. Unlike most of the prisoners there he does not belong to the Defias Brotherhood. Motley Garmason of Dun Modr wants him dead and blames human bureaucracy for letting him live.",["targorr the dread"]="Targorr the Dread was the supreme executioner of Gath'Ilzogg, a warlord of the Blackrock orcs in the Redridge Mountains. He tortured men who had fought bravely to defend the kingdom, and he did it on a whim, with a cruelty that shocked even his own kind.\n\nCaptured and sent to the Stormwind Stockade, he was sentenced to die. A noble put a hold on the execution, and the people of Lakeshire suspect foul play. When the prisoners rose against their guards, Targorr fell in with the Defias rioters."} },
  [36] = { name = "Deadmines", raid = false, levels = {17,20,15}, picture = "DEADMINES", where = {"Westfall",38.0,77.5}, quests = {{17,"Red Silk Bandanas","A","Scout Riell","Westfall","Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.",214},{18,"A Tauren Among Thieves","H","Sage Truthseeker","Thunder Bluff","Kill Mr. Smite in the Deadmines, beneath Moonbrook in Westfall, then return to Sage Truthseeker on the Elder Rise in Thunder Bluff.",9200047},{18,"Collecting Memories","A","Wilder Thistlenettle","Stormwind City","Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",168},{19,"The Ship Under the Hill","H","Sage Truthseeker","Thunder Bluff","Kill Captain Greenskin and Edwin VanCleef in the Deadmines, then return to Sage Truthseeker on the Elder Rise in Thunder Bluff.",9200048},{20,"Oh Brother. . .","A","Wilder Thistlenettle","Stormwind City","Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",167},{20,"Underground Assault","A","Shoni the Shilent","Stormwind City","Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",2040},{22,"The Defias Brotherhood","A","Gryan Stoutmantle","Westfall","Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.",166}}, stories = {["captain greenskin"]="Captain Greenskin is a goblin from Booty Bay, where he once led a fleet of pirate vessels. VanCleef gave him command of the juggernaut taking shape in the Deadmines, and he runs the ship with Mr. Smite as his first mate and Cookie in the galley. VanCleef means to use the juggernaut to lay waste to Stormwind from the sea.",["cookie"]="Cookie is a murloc who serves as the ship's cook aboard the juggernaut, in the service of Captain Greenskin and Edwin VanCleef. No one except VanCleef knows how or why he was given the post. The pirates do not seem to mind, since for them a meal is a meal.",["edwin vancleef"]="Edwin VanCleef was the guildmaster of the Stonemasons, the craftsmen who rebuilt Stormwind after the orcs burned it. He grew up in the city and learned a rogue's trade alongside his childhood friend Mathias Shaw. When the work was finished, the House of Nobles refused to pay what the guild was owed. VanCleef argued the case and was ignored, and he led his followers out of the city.\n\nIn the hills of Westfall he turned the Stonemasons into the Defias Brotherhood, a band of thieves and killers who wear red bandanas. They drove the farmers off their land and seized farms and mines across Westfall and Elwynn. VanCleef made his seat in the abandoned Deadmines under Moonbrook, where goblin engineers are building a great ship to strike at Stormwind from the sea.\n\nHe commands from the cabin of that ship. Baros Alexston, the city architect and an old friend, remembers him as a peerless fighter, an idealist and a romantic, and says revenge has consumed him.",["gilnid"]="Gilnid is a goblin of great skill as an engineer and the head smelter of the Defias operation. VanCleef's goblins built a foundry in the mines, and there Gilnid turns the steel and copper hauled in from the captured mines into the anchors and cannonballs the juggernaut needs.\n\nHe makes sure the ship is loaded with enough cannon and ammunition, and he tolerates no breaks until the work is done.",["mr smite"]="Mr. Smite is a tauren who serves as first mate under Captain Greenskin. It falls to him to keep the crew on its toes, and he is a skilled weaponmaster, trained in all manner of slicing, bashing and the occasional piercing shot.\n\nHe likes to play with his victims. He lets them believe they might win, then draws a more dangerous weapon, from a thief's blade to a pair of reavers and finally a mighty hammer.",["rhahkzor"]="Rhahk'Zor is an ogre and the Defias Brotherhood's head foreman in the Deadmines. The mines were abandoned when Stormwind fell in the First War, and now he runs them for Edwin VanCleef and oversees VanCleef's building projects. Ore, timber and metal flow into the caves from the mines and farms the Brotherhood has seized across Westfall and Elwynn.\n\nThe laborers answer to Rhahk'Zor, and he keeps them at work by \"motivating\" them. His methods are unconventional, but they get results.",["sneed"]="Sneed is a goblin the Defias Brotherhood hired as lumbermaster for his ruthless efficiency. He runs the Mast Room, where timber felled in Westfall is cut and shaped into the masts and rigging of VanCleef's juggernaut, a giant warship modeled on the orcish ships of the Second War.\n\nHis aim is simple. He wants the ship built as cheaply as it can be. To lead the work he built himself a lumber-slicing shredder, and riding it he gets terrifyingly fast results."} },
  [43] = { name = "Wailing Caverns", raid = false, levels = {17,20,15}, picture = "WAILINGCAVERNS", where = {"The Barrens",47.7,35.0}, quests = {{15,"Crocolisk Hunting","A","Marek Ironheart","Loch Modan","Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.",385},{16,"Hamuul Runetotem","H","Tonga Runetotem","The Barrens","Speak with Hamuul Runetotem.",1489},{16,"Nara Wildmane","H","Arch Druid Hamuul Runetotem","Thunder Bluff","Speak with Nara Wildmane.",1490},{17,"Deviate Hides","","Nalpak","Wailing Caverns","Nalpak in the Wailing Caverns wants 20 Deviate Hides.",1486},{18,"Serpentbloom","H","Apothecary Zamah","Thunder Bluff","Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",962},{18,"Smart Drinks","","Mebok Mizzyrix","The Barrens","Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",1491},{18,"Trouble at the Docks","","Crane Operator Bigglefuzz","The Barrens","Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",959},{21,"Deviate Eradication","","Ebru","Wailing Caverns","Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",1487},{22,"Leaders of the Fang","H","Nara Wildmane","Thunder Bluff","Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",914},{26,"The Glowing Shard","","Glowing Shard (an item)","","Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.",6981}}, stories = {["kresh"]="Kresh is a giant, ancient turtle who wanders the river and the caves near the entrance of the Wailing Caverns. The turtles that live there were not touched by Naralex's nightmare, and Kresh, whose resilient mind shrugs it off, goes about his life without noticing the evil around him. He has a happy disposition.",["lady anacondra"]="Lady Anacondra was once Scarletleaf, a young acolyte of the druid Naralex. She was the first to volunteer for his self-appointed mission to the Barrens, where he hoped to use the Wailing Caverns and the Emerald Dream to make the land green again.\n\nWhen Naralex's dream turned into a nightmare, it shattered her mind. She cast aside her name and now sees a sinister, reptilian future for Azeroth. She is one of the four Fanglords of the Druids of the Fang.",["lord cobrahn"]="Lord Cobrahn was once Jarlaxla, a druid whose skill at taking on animal forms made him renowned among the druids of the Cenarion Circle. The corruption of the Wailing Caverns twisted that gift.\n\nHe has since perfected a deadly serpentine form and taken the name Cobrahn to match his new, vicious strength. He stands much larger than the other druids, with a claw on his right hand and deviate pythons gathered around him, and he is one of the four Fanglords of the Druids of the Fang.",["lord pythas"]="Lord Pythas was once Aryn, a childhood friend of Naralex and a seasoned warrior in his personal guard. He took to druidism quickly, but the training did not protect him when the corruption came for his sanity.\n\nHe now goes by Pythas and joins his skill in melee fighting to a druid's magic against anyone who intrudes, standing with the Druids of the Fang.",["lord serpentis"]="Lord Serpentis was once the finest student of Naralex. He longed to become a shan'do, an honored teacher, as Naralex was, and that wish led to his downfall. When insanity took root in him, he rallied his brethren to his side and formed the Druids of the Fang.\n\nOnce a druid of great power and standing, he is corrupted by Naralex's nightmare and leads the Druids of the Fang in the depths of the caverns, with the thunder lizard Skum as his pet.",["mutanus the devourer"]="Mutanus the Devourer came out of the darkest corners of Naralex's twisted mind. The corruption that plagues the Emerald Dream took the shape of the druid's worst enemy, the murloc, and sent a colossal albino one into the waking world.\n\nWhatever force infected Naralex's dreams has ordered Mutanus to stop anyone from waking him. When the Disciple of Naralex tries the ritual to wake the sleeping druid, Mutanus appears to devour those who come to free him.",["skum"]="Skum is a thunder lizard who first came to the Wailing Caverns to escape the harsh environment of the Barrens. Like many of the caverns' other inhabitants, he soon gave in to the corruption. Dark energies now pulse through his veins and have turned him into a mighty, ruthless beast beyond redemption. He is kept in a small paddock in the Winding Chasm as the pet of Lord Serpentis.",["verdan the everliving"]="Verdan the Everliving is a huge elemental that formed long ago from the lush growth of the Wailing Caverns and served as their guardian. Little is known about it from the time before Naralex arrived.\n\nVerdan could not escape the corruption that spread through its home. The gentle giant has become an enormous abomination, allied with the insane druids, that crushes any living creature that comes too near its lair."} },
  [47] = { name = "Razorfen Kraul", raid = false, levels = {24,27,22}, picture = "RAZORFENKRAUL", where = {"The Barrens",42.2,89.8}, quests = {{26,"Going, Going, Guano!","H","Master Apothecary Faranell","Undercity","Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",1109},{27,"A Vengeful Fate","H","Auld Stonespire","Thunder Bluff","Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",1102},{27,"The Crone of the Kraul","A","Falfindel Waywarder","Feralas","Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",1101},{28,"Fire Hardened Mail","A","Furen Longbeard","Stormwind City","Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.",1701},{30,"Brutal Armor","H","Thun'grim Firegaze","The Barrens","Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.",1838},{30,"Mortality Wanes","A","Heralath Fallowbrook","Razorfen Kraul","Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",1142}}, stories = {["agathelos the raging"]="Agathelos the Raging is a colossal armored boar, roughly twice the size of a thunder lizard and larger still when enraged. Boars are revered in quilboar culture, and particularly large and tenacious ones are seen as a favor from Agamaggan, the titanic boar who is the god and progenitor of the quilboar.\n\nThe Death's Head keep him in a short tunnel in Razorfen Kraul, guarded by several quilboar who maintain a field to hold the beast in. Already powerful, Agathelos has been fed Kraul bat guano, which maddens him and adds to his stamina and strength. The Death's Head plan to use him as a weapon against all who oppose them.",["aggem thorncurse"]="Quilboar society has long favored shamanism, and the greatest shaman of a tribe are named prophets of Agamaggan. Calling on the power of their demigod ancestor, these prophets summon boar spirits to fight at their side, much as other shaman call spirit wolves.\n\nAggem Thorncurse is the Death's Head Prophet. The Death's Head tribe preaches that Agamaggan, the boar god who fell in the War of the Ancients, will rise from the dead, and its preachers are called speakers and prophets. Aggem holds his place among them in Razorfen Kraul.",["charlga razorflank"]="Charlga Razorflank, the Crone, rules the Razorfen tribes from deep inside Razorfen Kraul. She is a quilboar of unmatched skill in geomancy, and her rise to power was swift. Under her leadership the Razorfen conquered the great thorn mass of the Kraul and drove the tauren out of the southern Barrens.\n\nFrom the Kraul the quilboar now raid rival tribes and Horde villages, and violence between quilboar tribesmen is growing. Charlga is said to be negotiating with agents of the Scourge, aligning a tribe that does not suspect it with the undead for some purpose of her own. Her people revere Agamaggan, the great boar whose fall in the War of the Ancients is said to have raised the thorns around them.",["death speaker jargba"]="Death Speaker Jargba is a prophet of the quilboar religion that preaches the fallen god Agamaggan will rise from the dead. He is part priest and part warrior, and a powerful one in both roles.\n\nThe Death Speakers of the Death's Head tribe have two tasks. They spread the tribe's propaganda, and they discipline anyone who refuses to obey Charlga Razorflank and her mysterious new allies. Jargba has made a name for himself among them by dominating the minds of dissidents and forcing them to accept the will of their leaders.",["overlord ramtusk"]="Overlord Ramtusk commands the military forces of the Death's Head tribe. He is a massive, aging quilboar, and his thick hide carries the scars of many battles against centaurs, harpies, orcs and even tauren.\n\nAge has not slowed him. Ramtusk directs his troops with the swift, confident authority of a battle-forged veteran, and he goes to war crying out for victory and for Agamaggan. Two Razorfen Spearhides defend him with their lives. Striking him down would deal a crippling blow to the Death's Head.",["roogug"]="Among the quilboar, the reading of stones and crystals is held to be the highest form of shamanism. Roogug served his people for many years and spent them quietly honing the art, until he became the overseer of every geomancer in the Razorfen tribe.\n\nHe has gathered a powerful array of crystals and uses them to dispose of weaker foes. The mystics under his watch grow in number, and it is only a matter of time before they overrun the southern Barrens."} },
  [48] = { name = "Blackfathom Deeps", raid = false, levels = {21,24,19}, picture = "BLACKFATHOMDEEPS", where = {"Darkshore",33.4,93.5}, quests = {{22,"Allegiance to the Old Gods","H","Damp Note (an item)","","Bring the Damp Note to Je'neu Sancrea at Zoram'gar Outpost in Ashenvale.",6564},{22,"The Essence of Aku'Mai","H","Je'neu Sancrea","Ashenvale","Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.",6563},{22,"Trouble in the Deeps","H","Tsunaman","Stonetalon Mountains","Speak to Je'neu Sancrea in Ashenvale.",6562},{23,"Knowledge in the Deeps","A","Gerrig Bonegrip","Ironforge","Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",971},{24,"In Search of Thaelrid","A","Dawnwatcher Shaedlass","Darnassus","Seek out Argent Guard Thaelrid in Blackfathom Deeps.",1198},{24,"Researching the Corruption","A","Gershala Nightwhisper","Darkshore","Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",1275},{25,"The Orb of Soran'ruk","","Doan Karhan","The Barrens","Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",1740},{25,"Twilight Falls","A","Argent Guard Manados","Darnassus","Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",1199},{26,"Allegiance to the Old Gods","H","Je'neu Sancrea","Ashenvale","Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",6565},{27,"Amongst the Ruins","H","Je'neu Sancrea","Ashenvale","Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",6921},{27,"Blackfathom Villainy","A","Argent Guard Thaelrid","Blackfathom Deeps","Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",1200},{27,"Blackfathom Villainy","H","Argent Guard Thaelrid","Blackfathom Deeps","Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",6561}}, stories = {["akumai"]="Aku'Mai is a three-headed hydra and an ancient evil that carries a small measure of the Old Gods' power. The creature is feared for its mindless savagery and its insatiable hunger for living flesh.\n\nBlackfathom Deeps was once a great temple of Elune. The corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well, and Aku'Mai, a servant of that Old God, rose from the waters. The Twilight's Hammer cult worships the hydra as a divine sign that the Old Gods will soon return, and it sacrifices innocents to the beast.",["baron aquanis"]="Baron Aquanis is a water elemental that haunts the Moonshrine Ruins of Blackfathom Deeps. Somewhere underwater in the ruins lies a fathom stone, which holds a fathom core, a device that records the history of the elemental activity around it. Whoever lifts the core from the stone wakes the Baron.\n\nThe Earthen Ring has long thought of Aquanis as a corrupted elemental power. The Twilight's Hammer has moved into the ruins, and the shamans suspect the cult. A strange water globe, holding a putrid-looking form of water, seems to have fed the creature with energy.",["gelihast"]="Gelihast is a murloc who fights with two swords and strikes with incredible speed. He did not come from the underwater caves of Blackfathom Deeps. The Old Gods called, and he answered, forcing his way into the deeps and slaughtering nearly a dozen surprised Twilight's Hammer cultists with his twin blades.\n\nImpressed by his ferocity and brutality, the cult allowed him to stay. He built a shrine of his own, where he offers sacrifices and receives blessings from the ominous presence in the temple ruins. The Blindlight murlocs of the deeps follow him.",["ghamoo ra"]="Ghamoo-Ra is a giant turtle, once one of the last peaceful creatures living in the ruined temple of Elune. When the Twilight's Hammer cult arrived, its followers roused the turtle and imprisoned it. They delighted in tormenting the creature for years, flaying its mind and body until it gave way to madness.\n\nThe cultists gave the beast its name and trained it to attack outsiders and defend the Old Gods' shrine. It now roams a small island in the Pool of Ask'ar, surrounded by other turtles.",["lady sarevess"]="Lady Sarevess is a naga and a twisted spellcaster who dabbles deeply in the realm of magic. The Twilight's Hammer granted her a private cove in the Pool of Ask'ar of Blackfathom Deeps and keeps sending her fresh sacrifices.\n\nThe cultists want something in return. They hope her rituals and research will result in a magical protection that lets them worship the terrifying hydra at the heart of the deeps without fear of becoming its next meal. Sarevess has no welcome for visitors and orders them slain.",["lorgus jett"]="Lorgus Jett is a human of the Twilight's Hammer who calls down lightning on his enemies. He keeps to the long tunnels of the Moonshrine Ruins in Blackfathom Deeps, between the chamber of Ghamoo-Ra and the waters of Baron Aquanis.\n\nA crumpled note in his hand shows what he is after. The naga priestesses are to bring him crystals, and the water elemental spirits inside them will aid the cult's aquamancers in their summonings. By controlling the power in the crystals, the cult hopes to appease Aku'Mai and one day gather enough strength to bring the hydra back, so that the world returns to an era of rule by the Old Gods. The Earthen Ring, which found the note, names him as a follower who must be stopped.",["old serrakis"]="Old Serra'kis is a huge threshadon that lives in the Forgotten Pool, a submerged dead-end cavern reached by swimming past the Moonshrine Ruins of Blackfathom Deeps. After the Twilight's Hammer cult took up residence, many of the creatures swimming beneath the ruins were killed for food. The largest thresher proved uncatchable, and those who persisted in hunting it died in the attempt.",["twilight lord kelris"]="Twilight Lord Kelris is an orc and the leader of the Twilight's Hammer in Blackfathom Deeps, where a great temple of Elune once stood. The corruption of an Old God seeped up beneath the temple and tainted its sacred Moon Well, and the hydra Aku'Mai rose from the waters. The cultists allied with the naga to hold the grounds, and Kelris leads them in sacrificing innocents to Aku'Mai for power.\n\nWhen the cultists found the strange three-headed creature, Kelris became convinced it was a herald of the Old Gods' return and his ticket to immortality. He oversees its growth in person, even feeding it his own subjects to satisfy its hunger. Wherever evil showed itself in the region, the Argent Dawn found that Kelris had played a part."} },
  [70] = { name = "Uldaman", raid = false, levels = {37,40,35}, picture = "ULDAMAN", where = {"Loch Modan",34.8,85.1}, quests = {{36,"Power Stones","","Rigglefuzz","Badlands","Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",2418},{39,"Indurium","","Martek the Exiled","Badlands","Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.",1108},{40,"Power in Uldaman","","Tabetha","Dustwallow Marsh","Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.",1956},{43,"Find the Gems","A","Remains of a Paladin","Uldaman","Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.",2201},{44,"Find the Gems and Power Source","H","Jarkal Mossmeld","Badlands","Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.",2339},{44,"Restoring the Necklace","A","Talvash del Kissel","Ironforge","Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",2204}}, stories = {["ancient stone keeper"]="The Ancient Stone Keeper is one of many golems that staffed and operated the great titan vault of Uldaman. It belonged to a small group that stood between the watchers left in control of the facility and their many servants, and it keeps its post in the Temple Hall.\n\nThe corruption of the Obsidian Sentinel has left the Stone Keeper the last of its kind. It goes on protecting the secrets of the titans as best it can until its inevitable shutdown.",["archaedas"]="Deep within Uldaman lies a chamber with one of the greatest treasures of the titans, the Discs of Norgannon, which hold countless secrets of the Makers. No explorer has managed to reach it, for any attempt wakes the great watcher Archaedas.\n\nArchaedas is an immense guardian, crafted from some of the oldest, strongest stone taken from Uldaman's depths. He has a veritable army of stone servants at his command, and he calls them to defend the discs, demanding to know who dares the wrath of the Makers. Treasure seekers who try him are dispatched with ease.",["galgann firehammer"]="When Bronzebeard dwarves discovered Uldaman, the Dark Iron clan answered with an invasion of the vault. The Dark Irons meant to keep their ancestral foes from the powerful artifacts inside.\n\nGalgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation at Dig Three, so that the emperor could turn the artifacts' destructive power against the Dark Irons' enemies. Geologists of the Shadowforge guard him, and he swears by Thaurissan's beard as he orders intruders slain.",["grimlok"]="Among the troggs, the biggest, strongest and most vicious often becomes chieftain through displays of power. Grimlok rules the Stonevault troggs in the Stone Vault of Uldaman, and he calls himself king.\n\nHe is something of a genius by trogg standards. He has kept control through intimidation and what might be called crude psychological warfare. Grimlok trained a deadly basilisk, the Jadespine Basilisk, and the threat of petrification by his beast keeps any would-be usurper in line.",["ironaya"]="The titans did not build Uldaman directly. They used various servants to raise its megalithic halls, and the Pantheon entrusted the watcher Ironaya with overseeing the construction and upkeep of the complex. As time passed, the once awe-inspiring vault fell to ruin.\n\nIronaya has spent millennia in a form of stasis in the map chamber, studying the original master plan drawn up by Khaz'goroth and trying to find a way to restore the complex to its first function. She wakes when the Staff of Prehistoria is set in the map, and she cries out that none may steal the secrets of the Makers.",["obsidian sentinel"]="The Obsidian Sentinel is one of the stone keepers the titans built to protect Uldaman from would-be invaders and to oversee its daily operations. It was responsible for guarding the vault's secrets until an unknown force corrupted it.\n\nThe Sentinel was crafted from the same stone as the halls of Uldaman itself, but most of its body has been replaced with dark glass that reflects spells. Whatever caused the change must be incredibly potent, for it is not easy to alter the enchanted stone of a titan construct.",["revelosh"]="Revelosh is a trogg who prowls the Hall of the Keepers in Uldaman. Some luminaries of the Explorers' League in Ironforge have theorized an ancestral link between the dwarves and the troggs. They point to the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices.\n\nIf that is true, Revelosh is the trogg equivalent of an archaeologist. He holds the Shaft of Tsol, one half of the Staff of Prehistoria that opens the way to Ironaya. A dwarf with a historian's mind who meets him would be more inclined to call him a thief.",["the lost dwarves"]="Baelog, Eric and Olaf are three brothers who went into Uldaman seeking fame and, more to the point, fortune. They took a contract from the Explorers' League to clear a path for a group of researchers, but clearing a path turned into getting hopelessly lost in an ancient labyrinth. Then the troggs awoke and overran the dig site. The brothers have been trapped behind enemy lines at Dig Two ever since.\n\nBaelog, the muscle of the trio, worked out how to open the hidden Chamber of Khaz'mul. Olaf, unusually big and not particularly bright, bet him that his beard would reach his knees before they saw another non-trogg. Proud dwarves to the end, they fight to keep the secrets of Uldaman and the Explorers' League out of Horde hands."} },
  [90] = { name = "Gnomeregan", raid = false, levels = {25,28,23}, picture = "GNOMEREGAN", where = {"Dun Morogh",17.5,39.1}, quests = {{30,"Gyrodrillmatic Excavationators","A","Shoni the Shilent","Stormwind City","Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",2928},{35,"Rig Wars","H","Nogg","Orgrimmar","Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.",2841},{35,"The Grand Betrayal","A","High Tinker Mekkatorque","Ironforge","Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",2929}}, stories = {["crowd pummeler 9 60"]="In Gnomeregan's heyday, inventors competed for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot and earned the respect of the high tinker's court. Sicco Thermaplugg stole the blueprints, built a giant version of the machine and set his forgery loose.\n\nThe horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite stolen inventions.",["electrocutioner 6000"]="Mekgineer Thermaplugg has no patience for testing his inventions. He rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt to use electricity as a weapon, a super-charged mechano-tank.\n\nOnly one soldier survived piloting it, Lieutenant Tom \"Sizzlepants\" Crankle, one of the insane leper gnomes who still follow Thermaplugg. He still drives the machine, and among the leper gnomes he is something of a hero.",["grubbis"]="When Thermaplugg flooded Gnomeregan with radioactive gas, the plan was meant to anger the troggs and kill the gnomes, and it worked with brutal effect. One trogg reacted oddly to the substance. Grubbis grew, and kept growing. Thermaplugg had not anticipated the side effect, but he never wastes a valuable and dangerous resource.\n\nThe giant trogg now patrols the tunnels of Gnomeregan with his loyal basilisk, Chomper. The pair sniff out gas leaks and tasty fungi, and they like intruders even better.",["mekgineer thermaplugg"]="Sicco Thermaplugg was once an ambitious gnomish engineer and the chief advisor of High Tinker Gelbin Mekkatorque. In secret he envied his lord and wanted the title of high tinker for himself. When the troggs overran the lower levels of Gnomeregan, Thermaplugg convinced Mekkatorque to flood the city with radioactive gas. He meant the gas to anger the troggs and kill the gnomes.\n\nThe radiation proved far deadlier than he had reckoned. Nearly eighty percent of the gnomes died within days, and many survivors, Thermaplugg among them, were twisted into insane leper gnomes, while Mekkatorque led the rest to safety in Ironforge.\n\nThermaplugg now calls himself king of the gnomes and rules the radioactive halls of Gnomeregan from the Tinkers' Court. His subjects are numerous, vicious and mad enough to defend him against any intrusion from the upper world, and even the monsters of the city fear him. He has the cunning to destroy everything around him and no thought for his own life. Mekkatorque, who knows of the betrayal now, wants him dead.",["viscous fallout"]="The waterways of Gnomeregan were once elegantly complex. Now they are an irradiated mess filled with toxic slime. A lone water elemental that had lived in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form.\n\nViscous Fallout wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal."} },
  [109] = { name = "Sunken Temple", raid = false, levels = {47,50,45}, picture = "SUNKENTEMPLE", where = {"Swamp of Sorrows",77.4,35.4}, quests = {{50,"Into The Temple of Atal'Hakkar","A","Brohann Caskbelly","Stormwind City","Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.",1475},{50,"The Temple of Atal'Hakkar","","Fel'zerul","Swamp of Sorrows","Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.",1445},{51,"Into the Depths","","Marvon Rivetseeker","Tanaris","Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.",3446},{51,"Secret of the Circle","","Marvon Rivetseeker","Tanaris","Travel into the Sunken Temple and discover the secret hidden in the circle of statues.",3447},{51,"The Sunken Temple","H","Witch Doctor Uzer'i","Feralas","Find Marvon Rivetseeker in Tanaris.",3380},{52,"A Better Ingredient","","Torwa Pathfinder","Un'Goro Crater","Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.",9053},{52,"Ancient Evil","H","Lady Sylvanas Windrunner","Undercity","Unlock the secrets of the Temple of Atal'Hakkar to release Atal'alarion and recover the Putrid Vine from his flesh.  Return to Mehlar at the Bulwark when you have done this.",10593},{52,"Blood of Morphaz","","Ogtinc","Azshara","Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.",8257},{52,"Da Voodoo","","Bath'rah the Windwatcher","Alterac Mountains","Bring the voodoo feathers to Bath'rah the Windwatcher.",8413},{52,"Destroy Morphaz","","Archmage Xylem","Azshara","Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.",8253},{52,"Forging the Mightstone","A","Commander Ashlam Valorfist","Western Plaguelands","Collect Amber, Blue, and Green Voodoo Feathers from the trolls of Sunken Temple.",8418},{52,"Haze of Evil","A","Gregan Brewspewer","Feralas","Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.",4143},{52,"The Azure Key","","Archmage Xylem","Azshara","Return the Azure Key to Lord Jorach Ravenholdt.",8236},{52,"The Green Drake","","Ogtinc","Azshara","Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",8232},{52,"Trolls of a Feather","","Impsy","Felwood","Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.",8422},{52,"Voodoo Feathers","","Fallen Hero of the Horde","Swamp of Sorrows","Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.",8425},{52,"Zapper Fuel","H","Liv Rizzlefix","The Barrens","Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.",4146},{53,"Jammal'an the Prophet","","Atal'ai Exile","The Hinterlands","The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.",1446},{53,"The God Hakkar","","Yeh'kinya","Tanaris","Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.",3528},{55,"The Essence of Eranikus","","Essence of Eranikus (an item)","","Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.",3373},{60,"Eranikus, Tyrant of the Dream","","Malfurion Stormrage","","Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.",8733}}, stories = {["atalalarion"]="Atal'alarion is a dire troll of the Atal'ai tribe, huge even among trolls, and his title is Guardian of the Idol. He is the sworn protector of the idol that stands on the lowest floor of the sunken Temple of Atal'Hakkar.\n\nBy his own words he was banished once. When he rises he declares that the banishment has ended and that the blood will flow, and he promises to feast on the bones of anyone who comes near his charge.",["avatar of hakkar"]="Hakkar the Soulflayer is the Blood God of the Gurubashi trolls, a loa who grew stronger with every drop of blood spilled in his name. His demands for sacrifice never ended, and he longed to enter the physical world so that he could drink the blood of every living creature. In the end the jungle trolls rose against him. In a terrible war they destroyed his avatar and banished him from the world.\n\nThe avatar in the Temple of Atal'Hakkar is a skeletal wind serpent, the lasting presence of the god, and its spirit still haunts the drowned ruins as it waits for the right time to regain its power. Long ago Hakkar instructed the Atal'ai to bring forth his avatar with blood ritually drained from living victims. The priests who hold the temple now carry out their gruesome rituals in the hope of summoning him again, and if they succeed, his return could spell doom for Azeroth.",["dreamscythe"]="Dreamscythe is a young green drake who came to the Temple of Atal'Hakkar with Eranikus and three others. Ysera sent them to watch over the ruined temple, and the Emerald Nightmare tainted them there.\n\nHe still speaks like a warden. He tells intruders to turn back and not to wake the dreamer, and he says that they must be destroyed for their own good.",["hazzas"]="Hazzas is one of four young green drakes who followed Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. Ysera sent them to watch over the ruins, and for a while they kept the Atal'ai in check. One by one they were captured and tainted by the Emerald Nightmare.\n\nNow Hazzas stands with Morphaz in the hall that leads to the shade of Eranikus, and he lashes out at anyone who intrudes upon his waking dream.",["jammalan the prophet"]="Jammal'an is the spiritual leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar, and of the Hakkari of Zul'Gurub and the Swamp of Sorrows. He had what he calls a prophecy, in which the return of the Blood God will bring the Atal'ai immortality. Under his direction the Atal'ai and Hakkari sent their most skilled priests to Zul'Gurub, where Hakkar is to be summoned in the flesh.\n\nHis undead bodyguard Ogom the Wretched stands beside him. A troll exiled from the Atal'ai for urging caution suspects that the prophecy was only manipulation, and that Jammal'an's trust in false visions has led his people to doom. Jammal'an himself cries out that Hakkar shall live again.",["morphaz"]="Morphaz is a young green drake, one of four who came to the Temple of Atal'Hakkar under Eranikus. Ysera sent them to watch over the ruins, and for a time they held the Atal'ai in check. Then the Emerald Nightmare took them.\n\nYears ago Morphaz overwhelmed the archmage Xylem in a bold ambush and swallowed a whole apprentice. Xylem was little troubled by the loss of the young man. The apprentice had been carrying an arcane shard of unsurpassed size and quality, though, and Xylem wants it retrieved.",["shade of eranikus"]="Eranikus was among the greatest of the green dragons, consort to Ysera the Dreamer and keeper of a shard of the Scepter of the Shifting Sands. After Ysera smashed the Temple of Atal'Hakkar beneath the marshes, she sent him to guard its ruins and stop Hakkar from emerging, and four young drakes served under his command.\n\nInside the temple the dark forces of the place corrupted Eranikus and his retinue. He went mad not long after he entered and became one of the first dragons to fall to the Emerald Nightmare. Now he is a shade, pulled between the realms of the Emerald Dream and the physical world. Even so he can still spew corrosive acid and lull intruders into a deep slumber.",["weaver"]="Weaver is a young green drake, one of four who followed Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. Ysera had sent them to watch over the ruined temple. The Emerald Nightmare corrupted them there, and the trolls they were set to watch over took the dragons captive.\n\nWeaver keeps the central chamber of the temple together with Dreamscythe, and the two lash out at anyone who comes so far."} },
  [129] = { name = "Razorfen Downs", raid = false, levels = {34,37,32}, picture = "RAZORFENDOWNS", where = {"The Barrens",50.9,92.9}, quests = {{35,"A Host of Evil","","Myriam Moonsinger","The Barrens","Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.",6626},{36,"An Unholy Alliance","H","Bragor Bloodfist","Undercity","Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.",14353},{36,"An Unholy Alliance","H","Small Scroll (an item)","","Take the Small Scroll to Bragor Bloodfist at the Royal Quarter in the Undercity.",6522},{36,"An Unholy Alliance","H","Small Scroll (an item)","","Take the Small Scroll to Bragor Bloodfist in the Undercity.",14352},{36,"An Unholy Alliance","H","Varimathras","","Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.",6521},{37,"Bring the End","H","Andrew Brownell","Undercity","Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",3341},{37,"Bring the Light","A","Archbishop Benedictus","Stormwind City","Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.",3636},{37,"Extinguishing the Idol","","Belnistrasz","Razorfen Downs","Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.",3525},{37,"Scourge of the Downs","","Belnistrasz","Razorfen Downs","If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",3523}}, stories = {["amnennar the coldbringer"]="Amnennar the Coldbringer is a lich who took part in the Scourge's assault on Mount Hyjal during the Third War. Afterward the Lich King told his servant to stay in Kalimdor and widen the Scourge's reach, and Amnennar began to plan a base from which to strike at Orgrimmar and Theramore.\n\nFor that he turned to the quilboar, a displaced and desperate people. He promised them power over death so that they could drive off invaders, and he took control of the Death's Head tribe, turning the thorn maze of Razorfen Downs into a bastion of undead might. Through a direct telepathic link to Ner'zhul, the Lich King, he guides the quilboar with the power of his massive consciousness. He tells intruders that they will never leave alive.",["glutton"]="Glutton is a massive abomination who patrols the lower tier of the Spiral of Thorns. He has spent much of his time in Razorfen Downs gorging on the spoiled corpses of boars and their quilboar masters. The rancid meat in his gut gives off a cloud of noxious fumes and crippling disease. He snarls that he smells the stench of the living and means to feast on them all.",["mordresh fire eye"]="Mordresh Fire Eye was an orc shaman, sent from Orgrimmar to find out what was happening in Razorfen Downs. He was slain there and remade as an undead servant of the Scourge. The lord of Razorfen Downs judged the elements unreliable and filled him with blazing fel energies to sear the flesh of the living.\n\nIn mockery of his old calling as a spiritual leader, Mordresh now uses his power to drive lesser undead into a violent frenzy. He stands on a pile of skulls and bones and calls to the skeletons around him, promising that they will spread across the barren land and enslave the quilboar until the Scourge rules the world.",["plaguemaw the rotting"]="Plaguemaw the Rotting is an undead quilboar, a powerful warrior of the Death's Head tribe. Near the entrance of Razorfen Downs stands an idol that serves the quilboar as a grisly oven, where they consume the people they carry off from the Barrens.\n\nBelnistrasz, a prisoner of the Downs who is really a red dragon in human form, means to shut the idol down with a ritual. Plaguemaw comes to stop him.",["tutenkash"]="Tuten'kash is a crypt fiend, a large arachnid raised to serve the Scourge, and one of its deadliest commanders in Razorfen Downs. He was blinded before his conversion to undeath, and he makes up for it by hanging fine, almost invisible webs through his lair in the Caller's Chamber. The webs carry every footstep and the lightest touch to him, and he sends out his minions to ambush whoever has wandered in.\n\nStrong vibrations can drive him into a disoriented rage and draw him out of his hiding place deep in the recesses of the Downs."} },
  [189] = { name = "Scarlet Monastery", raid = false, levels = {29,40,27}, picture = "SCARLETMONASTERY", where = {"Tirisfal Glades",84.8,30.3}, quests = {{33,"Hearts of Zeal","H","Master Apothecary Faranell","Undercity","Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.",1113},{33,"Vorrel's Revenge","H","Vorrel Sengutz","Scarlet Monastery","Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",1051},{38,"Compendium of the Fallen","H","Sage Truthseeker","Thunder Bluff","Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",1049},{38,"Mythology of the Titans","A","Librarian Mae Paledust","Ironforge","Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",1050},{40,"In the Name of the Light","A","Raleigh the Devout","Hillsbrad Foothills","Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",1053},{42,"Into The Scarlet Monastery","H","Bragor Bloodfist","Undercity","Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.",14355},{42,"Into The Scarlet Monastery","H","Varimathras","","Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",1048}}, stories = {["arcanist doan"]="Arcanist Doan keeps the library of the Scarlet Monastery, a guardian of the arcane that the Scarlet Crusade is rumored to distrust. All the same he is a trusted official, counted among the most powerful mages of the Crusade, and he holds a vital key that grants access to Scarlet operations across the Plaguelands.\n\nDoan believes that arcane magic is the only way to rid Lordaeron of the Scourge. He guards the library's mysteries closely. He warns intruders that they will not defile them, and he calls down righteous fire on those who try.",["bloodmage thalnos"]="Bloodmage Thalnos earned a name in the Scarlet Crusade for the brutal methods he used to purify new recruits. The sadistic mage later caught the plague of undeath and rose again as a fearsome skeleton.\n\nThalnos still prowls the monastery graveyard. He commands apparitions and zombified creatures to attack anyone who trespasses on his unholy domain, and he says that the angry dead have no rest and that they hunger for vengeance.",["herod"]="Herod is the Scarlet Champion, one of the four leaders of the Scarlet Crusade in the Scarlet Monastery, and he holds its armory. He is a brutal fighter who says he has been waiting for a real challenge, and when a battle turns hard he calls on the Light to give him strength.\n\nHe has enemies outside the monastery. Raleigh the Devout in Southshore left the Crusade after he saw innocent men and women tortured as supposed plague carriers, and he wants its leaders dead. So does Varimathras in the Undercity, who wishes to end a threat so close to his capital.",["high inquisitor fairbanks"]="High Inquisitor Fairbanks was the most trusted advisor of Highlord Alexandros Mograine, a founder of the original Scarlet Crusade and the knight called the Ashbringer. Fairbanks followed him into an ambush by the Scourge at Stratholme, where Mograine's son Renault had led his father like a lamb to the slaughter.\n\nFairbanks fell first and the undead ignored him. He lay under the corpses for two days, heard Renault drive the Ashbringer through his father's heart, and then escaped the ruined city. He told the tale to anyone who would listen, and the Crusade murdered him for it and dragged his body to a hidden chamber. Some had listened, and from them the Argent Dawn was born. Fairbanks still lies in that chamber, undead.",["high inquisitor whitemane"]="Sally Whitemane was young when her family fell to the plague of undeath as they traveled through northern Lordaeron. She was forced to destroy her parents and siblings when they rose as mindless Scourge minions. Guilt and rage have left her with one source of fulfillment, the destruction of the undead.\n\nNow High Inquisitor Whitemane is the true master of the Scarlet Monastery, a fearsome priestess who directs the Crusade from its cathedral and can raise fallen warriors to fight in her name. Raleigh the Devout in Southshore and Varimathras in the Undercity both want her dead, one to return the Crusade to its first purpose and the other to end a threat so near his capital.",["houndmaster loksey"]="Houndmaster Loksey is one of the four leaders of the Scarlet Monastery, the captain who trains the hounds the Scarlet Crusade uses to track its enemies. He commands the loyalty of fearsome dogs that can tear a victim apart limb by limb within minutes, and he greets intruders with the cry to release the hounds.\n\nHis brother is Huntsman Leopold, the emissary the Crusade sent to Light's Hope Chapel as part of its reluctant alliance with the Argent Dawn. Leopold holds that Loksey cannot even take care of his own hounds, let alone represent the Crusade, which is why Leopold went in his place.",["interrogator vishas"]="James Vishas is the Scarlet Crusade's lead interrogator at the Scarlet Monastery. He enjoys torturing captured undead and takes great pride in his work. He is known for his unrelenting sadism, his cruel expertise and his high pitched voice, and his victims hear him demand that they tell him everything.\n\nFor weeks he has tortured Vorrel Sengutz, a Forsaken who lies on a torture table in the graveyard wing. Vishas took Sengutz's wedding ring and gave it to his own wife, Nancy, who lives with Grandpa Vishas in a cottage on the eastern shore of Lordamere Lake in the Alterac Mountains."} },
  [209] = { name = "Zul'Farrak", raid = false, levels = {43,46,41}, picture = "ZULFARAK", where = {"Tanaris",38.7,19.5}, quests = {{45,"Scarab Shells","","Tran'rek","Tanaris","Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.",2865},{45,"Troll Temper","","Trenton Lighthammer","Tanaris","Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.",3042},{46,"Tiara of the Deep","","Tabetha","Dustwallow Marsh","Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",2846},{47,"Divino-matic Rod","","Chief Engineer Bilgewhizzle","Tanaris","Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",2768},{47,"The Prophecy of Mosh'aru","","Yeh'kinya","Tanaris","Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.",3527}}, stories = {["antusul"]="Antu'sul is a Sandfury troll who raises the sul'lithuz basilisks of Zul'Farrak, and he prefers them strong and ruthless. He treats the scaled beasts like family and calls them his children, and he strikes down anyone, even a fellow troll, who harms them. He lives in a cave set into the hills beside the city.\n\nWhen intruders come he greets them with the words that lunch has arrived and tells his beautiful children to tear them to pieces. He gives his enemies no proper burial, and lets the basilisks feast on whoever dares cross him.",["chief ukorz sandscalp"]="Chief Ukorz Sandscalp rules the Sandfury tribe and its city, Zul'Farrak, and he is obsessed with restoring his people to their former glory. He was raised on stories of a time when trolls lorded over their ancient lands without interference from goblins, gnomes, pirates, ogres and other foreign interlopers. In his own day much of the Sandfury homeland lies in ruins, its cities squatted in by ogres and Wastewander bandits.\n\nSandscalp has called on his trusted comrade Ruuzlu to help him begin a new chapter in Sandfury history in the only way the tribe knows, with swift and blinding violence. He declares that the desert is his and that the Sandfury reign supreme.",["gahzrilla"]="Long ago, when trolls held the land that became Tanaris, they built Zul'Farrak around a sacred pool. From that pool they called up the huge hydra Gahz'rilla, a beast so fierce that her scales crackle with energy. The Sandfury have worshiped her as a deity for thousands of years, and her image is a common motif in the city's architecture. Ornaments modeled after her are called Gahz'ridian.\n\nLegend says Gahz'rilla was an adored pet of the Old Gods, or even a demigod in her own right. The trolls guard the secret of her summoning and fear her icy wrath. They rouse her only when they have enough sacrifices to feed her ravenous appetite.",["hydromancer velratha"]="Hydromancer Velratha is a sand troll of the Sandfury and a worldly member of her tribe. Unlike most Sandfury, she has traveled far, collecting knowledge and artifacts that help her command the sacred waters of Zul'Farrak. She seems to hold a prominent place in the priestly order.\n\nHer journeys have won her many enemies abroad. One is Tabetha, whose beautiful and powerful Tiara of the Deep was stolen by agents Velratha sent to her home while she was away. Velratha sees the great power she commands as justification for her past misdeeds.",["nekrum gutchewer"]="Nekrum Gutchewer has mysteriously lived far past his natural life, and his decaying body is still strong. A medallion he carries is rumored to have given him his unnatural long years, at a cost, and Thadius Grimshade in the Blasted Lands wants it to study its hidden powers.\n\nWith Shadowpriest Sezz'ziz, Nekrum has gathered sacrifices for the mythic beast Gahz'rilla, who slumbers at the heart of the city. Many troll followers eagerly await her awakening, and they will do anything to see the ritual through.",["shadowpriest sezzziz"]="Shadowpriest Sezz'ziz is a priest of the Sandfury who leads a host of some hundred trolls together with Nekrum Gutchewer. The two have gathered sacrifices for the mythic beast Gahz'rilla, who slumbers at the heart of the city. Many troll followers eagerly await the creature's awakening, and they will do anything to see the ritual through.",["theka the martyr"]="Theka the Martyr is a historical figure in Sandfury society, a troll who gave his life for his people. Long ago he was slain in a brutal war between the qiraji and the trolls, and Zul'Farrak still stands because of his sacrifice. The dozens of insectoid warriors who killed him were cursed to live as mindless scarabs.\n\nEven in death he keeps a vigil over the city he loved. He is an undead sand troll now, and the scarabs scuttle at his side.",["witch doctor zumrah"]="Witch Doctor Zum'rah is a cruel Sandfury witch doctor. The Sandfury learned to raise the dead with voodoo so that every troll could keep working after death, and Zum'rah takes the practice further. Many of the tribe's fallen are offered no protection by a loa after death, and their tortured spirits obey him. He uses his dark magic to force the city's dead into unending service.\n\nHe guards his sanctum among the graves of Zul'Farrak, and he greets trespassers with a demand to know how they dare enter, and with a curse that the sands consume them."} },
  [229] = { name = "Blackrock Spire", raid = false, levels = {57,63,55}, picture = "BLACKROCKSPIRE", where = {"Burning Steppes",33.2,24.9}, quests = {{58,"The Final Tablets","","Prospector Ironboot","Tanaris","Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",4788},{59,"Bijou's Belongings","A","Bijou","Blackrock Spire","Find Bijou's Belongings and return them to her. Good luck!",5001},{59,"Bijou's Belongings","H","Bijou","Blackrock Spire","Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.",4982},{59,"Bijou's Reconnaissance Report","","Bijou","Blackrock Spire","Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath.",4983},{59,"En-Ay-Es-Tee-Why","","Kibler","Burning Steppes","Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\n\nBy the sound of it, these eggs could be found near spiders.",4862},{59,"Kibler's Exotic Pets","","Kibler","Burning Steppes","Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.",4729},{59,"Message to Maxwell","","Bijou","Blackrock Spire","Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.",5002},{59,"Operative Bijou","","Lexlort","Badlands","Travel to Blackrock Spire and find out what happened to Bijou.",4981},{59,"Put Her Down","","Helendis Riverhorn","Burning Steppes","Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.",4701},{59,"The Pack Mistress","H","Galamav the Marksman","Badlands","Slay Halycon, pack mistress of the Bloodaxe worg.",4724},{60,"Blackhand's Command","","Blackhand's Command (an item)","","That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.",7761},{60,"Blood of the Black Dragon Champion","H","Rokaro","Desolace","Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rokaro.",6602},{60,"Delivery to Ridgewell","A","Mayara Brightwing","Burning Steppes","Bring Ridgewell's Crate to Count Remington Ridgewell at Stormwind Keep in Stormwind.",4765},{60,"Doomrigger's Clasp","A","Mayara Brightwing","Burning Steppes","Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.",4764},{60,"Egg Collection","","Tinkee Steamboil","Burning Steppes","Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.",4735},{60,"Egg Freezing","","Tinkee Steamboil","Burning Steppes","Use the Eggscilloscope Prototype on an egg in the Rookery of Blackrock Spire.",4734},{60,"Eye of the Emberseer","","Duke Hydraxis","Azshara","Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.",6821},{60,"Falrin's Vendetta","","Falrin Treeshaper","Dire Maul","Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.",8949},{60,"Final Preparations","","Bodley","Blackrock Mountain","Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.",8994},{60,"Finkle Einhorn, At Your Service!","","Finkle Einhorn","","Talk to Malyfous Darkhammer in Everlook.",5047},{60,"For The Horde!","H","Thrall","Orgrimmar","Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.",4974},{60,"General Drakkisath's Command","A","General Drakkisath's Command (an item)","","Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.",5089},{60,"General Drakkisath's Demise","A","Marshal Maxwell","Burning Steppes","Travel to Blackrock Spire and slay General Drakkisath.",5102},{60,"Maxwell's Mission","A","Marshal Maxwell","Burning Steppes","Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.",5081},{60,"Mayara Brightwing","A","Count Remington Ridgewell","Stormwind City","Speak with Mayara Brightwing at Morgan's Vigil in the Burning Steppes.",4766},{60,"Mea Culpa, Lord Valthalak","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.",8995},{60,"Mother's Milk","","Ragged John","Burning Steppes","In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.",4866},{60,"Oculus Illusions","H","Myranda the Hag","Western Plaguelands","Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.",6569},{60,"Seal of Ascension","","Vaelan","","Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.",4742},{60,"Seal of Ascension","","Vaelan","","Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\n\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",4743},{60,"Snakestone of the Shadow Huntress","","Kilram","Winterspring","Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.",5306},{60,"The Darkstone Tablet","","Shadowmage Vivian Lagrave","Badlands","Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.",4768},{60,"The Demon Forge","","Lorax","Winterspring","Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.",5127},{60,"The Left Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",8966},{60,"The Matron Protectorate","","Awbee","Blackrock Spire","Travel to Winterspring and find Haleh. Give her Awbee's scale.",5160},{60,"The Right Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",8989},{60,"Three Kings of Flame","","Bodley","Blackrock Mountain","Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.",8961},{60,"Tinkee Steamboil","","Felnok Steelspring","Winterspring","Speak with Tinkee Steamboil at Flame Crest in the Burning Steppes.",4907},{60,"Urok Doomhowl","","Warosh","Blackrock Spire","Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh.",4867},{60,"Vivian Lagrave and the Darkstone Tablet","","Apothecary Zinge","Undercity","Speak with Shadowmage Vivian Lagrave.",4769},{60,"Warlord's Command","H","Warlord Goretooth","Badlands","Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",4903}}, stories = {["general drakkisath"]="General Drakkisath is a black dragonspawn who rules the dragonspawn armies of Nefarian, son of Deathwing. He holds the pinnacle of Blackrock Spire, in a throne room behind the Halls of Ascension, and he took the rank of General of Blackrock Spire after Lord Valthalak. A cunning and ruthless strategist, he commands Nefarian's armies in their war against Ragnaros.\n\nFrom his throne he directs the drive to push the Dark Iron dwarves out of the depths of Blackrock Mountain. His forces have already won victories against the dwarves, and they stand ready to clear them from the mountain once and for all.",["gizrul the slavener"]="Gizrul the Slavener is the mate of Halycon, and very few of the Dark Horde have ever laid eyes on him. He is a reclusive and unpredictable beast who keeps to a shadowy den and comes out only when Halycon calls to him. Together the two have sired some of the largest and most ferocious worgs in the history of the orcs. Nobody who has met him has lived to describe him.",["halycon"]="Halycon is a giant red and black worg, the den mother of the Blackrock orcs' war pack. She comes from a long line of great worgs bred for ferocity and loyalty, and over the years she has borne an astonishing number of savage offspring with her mate, Gizrul the Slavener. The orcs take her pups as mounts and hunting beasts, and in return Halycon and her brood are fed captured Dark Iron dwarves, whose gnawed remains litter the floor of her lair.\n\nRumor says she is a demonic hound that a pit lord of the Burning Legion gave to Rend Blackhand. The truth is plainer and just as frightening. The worgs of Blackrock come from Halycon and her mate, and from no demon.",["highlord omokk"]="Highlord Omokk rules the Spirestone ogres from Mok'Doom, a dead-end hall in the lower spire reached by a short stone bridge. The Spirestone clan follows Rend Blackhand and the Dark Horde and makes up a large part of the force that holds Blackrock Spire. Omokk keeps his title with an iron fist. Underlings have challenged him to single combat again and again, hoping to take it, and every one of them has fallen without landing a blow.\n\nThe ogres whisper that dark magic protects him, and they are right. Omokk is the face of the clan and Urok Doomhowl is its true master. Urok's boon strikes dead any ogre who lifts a hand against the highlord, so only someone who is not an ogre could ever end his rule.",["lord valthalak"]="Lord Valthalak was a drakonid noble and a warlock of immense power. Before General Drakkisath rose to power, Valthalak was General of Blackrock Spire, and he held the chamber in the upper spire where the Beast now prowls. A necromancer as well as a warlock, he kept a spellbook of great value and wore a magical amulet.\n\nA goblin smuggler from Booty Bay, Gremnik Rizzlesprang, hired the Veiled Blade mercenary company to steal that book. The mercenaries killed Valthalak and pried the book from his hands, then fought over the amulet and broke it into pieces. His revenge came after his death. Valthalak's spirit sent spectral assassins to hunt the company down one by one, and it still demands that what was stolen be returned.",["mother smolderweb"]="Mother Smolderweb is an enormous crystal spider and the matriarch of the spire spiders. Her lair stayed buried until, centuries ago, Dark Iron dwarves dug into it and let her loose in the halls of Blackrock Spire. She settled in the Skitterweb Tunnels, which climb from the lower reaches of Hordemar City toward the ogres' ledge, and she keeps laying eggs, so her brood grows larger every year.\n\nThe Blackrock orcs talk about the lethal venom they call Mother's Milk, which is named after her. Even Blackhand's warriors fear to travel through her domain.",["overlord wyrmthalak"]="Wyrmthalak is a black dragonspawn and the overlord and taskmaster of the lower spire, the lesser city of the Blackrock citadel. He holds the Chamber of Battle at its heart, where envoys of the Smolderthorn trolls, the Spirestone ogres and the Blackrock orcs all take his orders. He is the leader of the Bloodaxe Legion, and he answers to General Drakkisath above him.\n\nHis loyalty belongs to Nefarian alone. Wyrmthalak has no love for the false Horde or its brutish warriors, and he would sacrifice any number of Blackhand's minions to protect his master. For now he oversees the lower spire's forces as they prepare their assault on the dwarves.",["pyroguard emberseer"]="Pyroguard Emberseer is a fire elemental who served Ragnaros the Firelord. Long ago, in a great battle in the Burning Steppes, he incinerated dozens of Blackrock orcs. In the end he was beaten and taken prisoner, and his captors carried him into Blackrock Mountain and bound him in the Hall of Binding in the upper spire.\n\nBlackhand Incarcerators keep the prison closed with channeled magic, and the orcs who tend it stay locked in a trance. Emberseer's great energy is drawn off and used to speed up the hatching of Nefarian's black dragon eggs in the chambers beyond.",["quartermaster zigris"]="Zigris was an orc hunter in the years after the First War, and he became infamous for tracking down Stormwind refugees and slaughtering them like game. He now serves the Bloodaxe Legion as quartermaster of the spire's storehouse, where the Blackrock orcs keep their weapons, armor and ammunition. There he barks orders at his underlings while he inspects the crates and barrels.\n\nThe close, crowded halls of Blackrock Spire sit badly with a hunter. Zigris hates them, and he is certain that a day will come when he will hunt in the open air again.",["shadow hunter voshgajin"]="Vosh'gajin is a forest troll of the Smolderthorn tribe and a shadow hunter, schooled in the old troll arts of hexes, curses and healing. Among trolls she is renowned for her beauty and just as well known for a psychotic streak. She holds the halls of Tazz'Alor together with War Master Voone.\n\nHer cruelty has a long memory. The troll weaponsmith Kilram, who now works in Everlook in Winterspring, was once her lover. He still carries the scar she gave him, which she called a love tap, and he wants vengeance. Legend says that one use of her snakestone will keep an axe razor sharp for a thousand years.",["the beast"]="The Beast is a core hound, one of the fiery hounds that serve Ragnaros the Firelord. Nefarian's dragonkin captured him and tortured him for their amusement, as they delight in doing to the Firelord's captured minions. Where others broke, the Beast stayed lucid through the agony, and the dragonkin retrained him as a guard for the upper spire. His ferocity makes him ideal for the work.\n\nHe now holds the Furnace, the chamber that once belonged to Lord Valthalak. In the pits at the Molten Span he swallowed a gnome whole. Pip Quickwit, an inventor testing a lava-proof suit, has lived in the Beast's belly for some time.",["urok doomhowl"]="Urok Doomhowl is the real power among the spire's ogres. Highlord Omokk wears the title, but Urok charmed his trusted aide with insidious magic and rules the ogres through him. Any ogre who challenges the highlord is struck down, and Urok has gone to ruthless lengths to keep up the pretense.\n\nHe is cruel to those who challenge him directly. Warosh, once a great mage of the Spirestone clan, stood against him. Urok stole Warosh's mojo and cursed him into the shape of a trogg, and the ogre mage still wanders the lower spire in that form.",["war master voone"]="Voone leads the Smolderthorn, a tribe of forest trolls that joined the Dark Horde after the Second War. In that war he led small strike teams on daring raids into the heart of high elf territory. He has never believed in Blackhand's creed. He joined the false Horde because he wanted to be its chief strategist, and a splinter faction fighting against the odds suits him, since he enjoys overcoming a hopeless fight.\n\nVoone rules Tazz'Alor beside the shadow hunter Vosh'gajin, and he is a torturer as well as a commander. Mor Grayhoof, a tauren druid of the Veiled Blade mercenary company, fell into the lower spire and was tortured by Voone's trolls until he was nearly dead. His ghost still haunts Voone's chamber.",["warchief rend blackhand"]="Dal'rend Blackhand, called Rend, is the bloodthirsty son of Blackhand the Destroyer, the first Warchief of the Horde. When the Horde fell in the Second War, Rend and his brother Maim led the remnants of their clan into Blackrock Spire and made it their stronghold. There Rend declared himself Warchief and gathered orcs, forest trolls and ogres into the Dark Horde, which calls itself the true Horde. He holds that his bloodline gives him the right to lead the Horde, and he means to overthrow Thrall.\n\nThe spire was already held by the Dark Iron dwarves, and Rend and Maim fought them for it in a long war. The dwarves were driven from the upper halls only after Maim had died and the black dragons had come. Rend allied with Nefarian, and the two have worked to create the chromatic dragonflight, which they hope to unleash on the world. Rend rides to war on Gyth, a huge chromatic drake."} },
  [230] = { name = "Blackrock Depths", raid = false, levels = {49,56,47}, picture = "BLACKROCKDEPTHS", where = {"Searing Gorge",27.6,72.4}, quests = {{1,"Rocknot's Ale","","Private Rocknot","Blackrock Depths","",4295},{52,"Commander Gor'shak","H","Galamav the Marksman","Badlands","Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.",3981},{52,"Dark Iron Legacy","","Franclorn Forgewright","Blackrock Mountain","Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.",3802},{52,"Dark Iron Legacy","","Franclorn Forgewright","Blackrock Mountain","Speak with Franclorn Forgewright at Forgewright's Tomb in Blackrock Mountain if you are interested in obtaining a key to the city major.",3801},{52,"KILL ON SIGHT: Dark Iron Dwarves","H","WANTED","","Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.",4081},{53,"Ribbly Screwspigot","","Yuka Screwspigot","Burning Steppes","Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",4136},{53,"Yuka Screwspigot","","Yorba Screwspigot","Tanaris","Speak with Yuka Screwspigot in the Burning Steppes.",4324},{54,"KILL ON SIGHT: High Ranking Dark Iron Officials","H","KILL ON SIGHT","","Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.",4082},{54,"The Eastern Kingdoms","H","Thrall","Orgrimmar","Speak with Thrall if you are prepared to take on the mission he has planned.",4002},{54,"The Last Element","H","Shadowmage Vivian Lagrave","Badlands","Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.",7201},{54,"The Love Potion","","Mistress Nagmara","Blackrock Depths","Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.",4201},{54,"What Is Going On?","H","Commander Gor'shak","Blackrock Depths","Defend Gor'shak.",3982},{54,"What Is Going On?","H","Commander Gor'shak","Blackrock Depths","Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.",4001},{55,"Hurley Blackbreath","A","Ragnar Thunderbrew","Dun Morogh","Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",4126},{55,"Lost Thunderbrew Recipe","","Shadowmage Vivian Lagrave","Badlands","Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.",4134},{55,"Ragnar Thunderbrew","A","Enohar Thunderbrew","Blasted Lands","Speak with Ragnar Thunderbrew.",4128},{55,"The Heart of the Mountain","","Maxwort Uberglint","Burning Steppes","Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.",4123},{55,"The Spectral Chalice","","Spectral Chalice","","",4083},{55,"Vivian Lagrave","","Apothecary Zinge","Undercity","Speak with Shadowmaster Vivian Lagrave in Kargath.",4133},{56,"Disharmony of Fire","H","Thunderheart","Badlands","Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",3907},{56,"Incendius!","A","Jalinda Sprig","Burning Steppes","Find Lord Incendius in Blackrock Depths and destroy him!",4263},{56,"The Good Stuff","A","Oralius","Burning Steppes","Collect 20 Dark Iron Fanny Packs.",4286},{58,"A Taste of Flame","","Cyrus Therepentous","Burning Steppes","Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous.",4024},{58,"Grark Lorkrub","","Lexlort","Badlands","Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.",4122},{58,"Operation: Death to Angerforge","H","Warlord Goretooth","Badlands","Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.",4132},{58,"Precarious Predicament","H","Grark Lorkrub","Burning Steppes","Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.",4121},{58,"The Rise of the Machines","H","Lotwil Veriatus","Badlands","Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",4063},{59,"Kharan Mighthammer","A","King Magni Bronzebeard","Ironforge","Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.",4341},{59,"Kharan's Tale","A","Kharan Mighthammer","Blackrock Depths","Listen as Kharan Mighthammer tells his story.",4342},{59,"The Bearer of Bad News","A","Kharan Mighthammer","Blackrock Depths","Return to Ironforge and deliver the bad news to King Magni Bronzebeard.",4361},{59,"The Fate of the Kingdom","A","King Magni Bronzebeard","Ironforge","Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.",4362},{59,"The Princess's Surprise","A","Princess Moira Bronzebeard","Blackrock Depths","Return to Ironforge and speak with King Magni Bronzebeard.",4363},{59,"The Royal Rescue","H","Thrall","Orgrimmar","Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.",4003},{60,"A Binding Contract","","Thorium Brotherhood Contract (an item)","","Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",7604},{60,"The Challenge","","Falrin Treeshaper","Dire Maul","Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.",9015},{60,"The Princess Saved?","H","Princess Moira Bronzebeard","Blackrock Depths","Return to Thrall at Grommash Hold in Orgrimmar.",4004},{60,"Three Kings of Flame","","Bodley","Blackrock Mountain","Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.",8961}}, stories = {["ambassador flamelash"]="Ambassador Flamelash is a Flamewaker and a servant of Sulfuron Harbinger. His unwavering service to Ragnaros won him the rank of ambassador to the Dark Iron clan. At first this depraved being despised his dwarven allies, but he has come to respect their taste for destruction.\n\nAs a show of solidarity he guards the Chamber of Enchantment, a sacred place where the dwarves empower their weapons. It was Flamelash who charged the molten giant Magmus with guarding the emperor's throne room.",["baelgar"]="Bael'Gar is a molten giant, a being of pure flame born of the fires of Ragnaros. He lumbers along the Dark Iron Highway, a stunning feat of dwarven engineering carved into Blackrock Depths.\n\nRagnaros posted him at one end of the highway to guard a massive sealed door. According to legend, only the Firelord and the highest-ranking members of the Dark Iron clan know what lies beyond it.",["emperor dagran thaurissan"]="Emperor Dagran Thaurissan rules the Dark Iron clan. He descends from Sorcerer-Thane Thaurissan and Modgud, and it was the sorcerer-thane who first called Ragnaros the Firelord into Azeroth. Under Ragnaros's control Dagran tore the heart out of Blackrock Mountain and raised Blackrock Spire. He rules not from the city his forebear founded but from the depths near the gates of the Molten Core, with charisma, sorcery and an iron will.\n\nHe took the hammer Ironfoe from the captive Marshal Windsor and wields it himself. At his side sits Princess Moira Bronzebeard of the rival Bronzebeard clan. Debate rages over whether he ensorcelled his bride or she joined him willingly. Whatever the truth, so long as he lives the Dark Irons remain pawns of Ragnaros, and a dire threat to kingdoms throughout Azeroth.",["fineous darkvire"]="Fineous Darkvire is chief architect of the Dark Iron dwarves in Shadowforge City, a title he earned by passing off the ideas of more gifted masons as his own. He took the post after Franclorn Forgewright, the builder behind the stonewrought method and much of the Dark Iron stronghold, and with it came Franclorn's great hammer, Ironfel.\n\nFranclorn's will to live gave way once the Spire was finished, but his ghost has no peace. He sees Darkvire as a man of little talent and bad motives, and fears that a craftsman with real skill could one day use Ironfel to build something disastrous. The ghost wants the hammer back before it can be put to ill use.",["general angerforge"]="General Angerforge commands the armies of the Dark Iron clan. A lifetime of study made him an expert on dwarven military history and tactics, and he put that learning into a scathing treatise on his clan's failures in past conflicts. The treatise earned him the fury of Emperor Dagran Thaurissan.\n\nPolitics aside, Angerforge is Dark Iron to the core and will bleed, and die if need be, to protect his people and his emperor. The Horde knows him as the Butcher of Blackrock, and Warlord Goretooth blames him for the attacks that slaughtered the 109th division of the Kargath Expeditionary Force. Marshal Windsor believes that Angerforge holds part of the information the Dark Irons took from him.",["golem lord argelmach"]="Golem Lord Argelmach has spent his life chasing immortality. He forged enchanted constructs in his own image, and rumor says he has turned to a black magic that would let those creations carry his spirit if his flesh-and-blood body were ever destroyed.\n\nThe rumor has some support. Before the Third War a gnome scholar named Lotwil Veriatus killed Argelmach, yet the golem lord went on commanding the Manufactory from his private room, guarded by two golems. The Horde wants his head. When it was brought to Lotwil, it proved to be one more Dark Iron creation, and another would rise in time. Marshal Windsor believes Argelmach also holds part of his lost information.",["high interrogator gerstahn"]="High Interrogator Gerstahn is a cultist of the Twilight's Hammer who keeps the Detention Block of the Dark Iron clan. She has always indulged in life's finer things, from exotic foods and fine clothes to torture tools set with gems.\n\nPrisoners fill the cells around her, and their cries echo through the halls day and night. Gerstahn calls the noise her symphony of screams and is always eager to add another voice to the chorus. She alone carries the key that opens every cell.",["houndmaster grebmar"]="Grebmar Fleabeard was orphaned long ago, and the hounds he began breeding as companions and guard dogs are the only family he has known. The houndmaster keeps his pack beneath the arena and patrols Blackrock Depths with his loyal beasts.\n\nWhen he is off duty he takes the dogs to the Grim Guzzler and treats them to the tavern's finest Dark Iron ale. He is close friends with Warder Stilgiss, to whom he once gave one of his vicious dogs, a red hound named Verek.",["hurley blackbreath"]="To call Hurley Blackbreath a regular at the Grim Guzzler is an understatement. In more than a decade the mischievous drunk has left the tavern only once, to steal a top-secret recipe for Thunderbrew Lager. Now and then he sobers up enough to brew it himself, and he claims the lager grants unimaginable strength and courage.\n\nRagnar Thunderbrew in Kharanos wants his family's recipe back and every keg destroyed. Hurley guards his kegs fiercely and shouts at anyone who goes near them.",["lord incendius"]="Lord Incendius is a fire elemental who learned to harness his destructive powers from Baron Geddon in the Molten Core. The student proved far more efficient than his teacher expected, and Geddon began to fear that Incendius might take his place.\n\nTo be rid of the danger, Geddon sent the blazing elemental out of the Molten Core. Incendius now guards the Black Anvil, the fabled anvil of the Dark Iron dwarves in Shadowforge City.",["lord roccor"]="Lord Roccor is a fire elemental who cannot stand his own kind. The elementals of the Molten Core spend their time scheming and backstabbing one another, and Roccor wanted no place among them. He got his wish by angering Ragnaros, the Firelord, on purpose.\n\nThe gamble worked. Ragnaros expelled him from the core and set him to guard Blackrock Depths, where Roccor patrols the Halls of the Law with no company at all.",["magmus"]="Magmus is a molten giant of living fire. Ambassador Flamelash charged him with guarding the throne room of Emperor Dagran Thaurissan, but even that did not settle the emperor's fears. Ever wary of assassins, Thaurissan also gave Magmus control over a row of fire-breathing statues outside his royal chambers.\n\nFrom the Iron Hall, Magmus warns intruders that the emperor does not wish to be disturbed and tells them to turn back now or face their doom.",["phalanx"]="Phalanx is the bouncer of the Grim Guzzler, a tavern in the depths of Blackrock Mountain. Until recently, drunken brawls raged there almost every day. The barkeep, a leper gnome named Plugger Spazzring, cut them down by installing Phalanx, a mighty golem programmed to keep order and to remove raucous patrons with extreme force.\n\nOn a peaceful night Phalanx is friendly company. When trouble starts he stands against the crowd and declares that none shall pass.",["princess moira bronzebeard"]="Princess Moira Bronzebeard is the daughter of King Magni Bronzebeard of Ironforge, and she sits beside Emperor Dagran Thaurissan in the Imperial Seat. Kharan Mighthammer, the guard Magni assigned to watch over her, failed in his task and now sits in a cell of the Detention Block.\n\nMagni believes that Thaurissan holds his daughter under an evil spell that only the emperor's death can break. Moira tells a different story. She calls Thaurissan a great and honorable dwarf, and she carries his unborn child. If the emperor falls she weeps for him and declares that the heir to Ironforge will be a Dark Iron dwarf, whether her father approves or not.",["pyromancer loregrain"]="Pyromancer Loregrain is a tauren shaman who joined the Twilight's Hammer cult. His reasons remain a mystery. He made his way to the depths of Blackrock Mountain and took a sudden interest in Franclorn Forgewright, the famed Dark Iron architect, and he now kneels before the monument raised in the architect's honor.\n\nWhat he wants from Franclorn is unclear. Loregrain stays loyal to his cult and is an enemy of all who oppose it.",["ring of law"]="The Dark Iron clan has one punishment for crimes committed against it, and that punishment is death. By ancient tradition the guilty pay the blood price in the Ring of the Law, where they must fight savage creatures gathered from across Azeroth.\n\nHigh Justice Grimstone presides. He appears in the ring to pronounce the sentence and declares that the Sons of Thaurissan will watch the condemned perish. Crowds gather on the upper levels to watch. After the first beasts fall, Grimstone returns to announce that the real punishment lies ahead. To this day nobody knows whether anyone has survived the ring.",["the seven"]="The Seven were the patriarchs of the Dark Iron nation, dwarves of great knowledge and power. When Sorcerer-Thane Thaurissan lost the War of the Three Hammers, they joined him in delving into forbidden lore and accidentally summoned Ragnaros the Firelord at the place now called the Molten Core. The Dark Irons had no idea how much power they had called up. Thaurissan, the Seven and many of their people died in the blaze, which destroyed a great part of the Redridge Mountains and raised the black peak of Blackrock Spire.\n\nTheir clan was enslaved to the Firelord, yet the Seven seem to think his coming was a blessing. Their restless spirits, Anger'rel, Doom'rel, Dope'rel, Gloom'rel, Hate'rel, Seeth'rel and Vile'rel, linger in Blackrock Depths, cursed to serve their elemental master and the current ruler of the Dark Irons.",["warder stilgiss"]="Warder Stilgiss is a Dark Iron mage who spent years in devoted service to Emperor Thaurissan. The emperor's trust brought him the task of protecting the clan's coffers in the Black Vault.\n\nHis close friend Houndmaster Grebmar marked the occasion with a gift, one of his vicious dogs, a red hound named Verek. Stilgiss keeps the beast at his side to scare off the vault's would-be thieves."} },
  [249] = { name = "Onyxia's Lair", raid = true, levels = {80,83,80}, where = {"Dustwallow Marsh",52.9,78.2}, quests = {{60,"A Proper String","","Stoma the Ancient","Felwood","Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.",7635}}, stories = {["onyxia"]="Onyxia is a daughter of Deathwing and the twin of Nefarian, the tyrant of Blackrock Spire. She is small for a black dragon of her age, and clever. Her breath melts stone and iron, and her bites and tail lashes are quick and nearly impossible to avoid. Cornered, she takes to the air and burns her enemies from above. She is one of Nefarian's mightiest supporters and has been seen traveling to and from Blackrock Mountain.\n\nOnyxia likes mortal shapes, because they let her steer the affairs of kingdoms in secret. In Stormwind she lives as Lady Katrana Prestor, the noblewoman who stands beside the boy king Anduin Wrynn. With a pendant known as the Dragon's Eye she has bent Highlord Bolvar Fordragon to her will. Marshal Reginald Windsor exposed her in Stormwind Keep and died for it, and she fled.\n\nHer lair is a fiery cave in the Wyrmbog of Dustwallow Marsh. Her brood has overrun the ogre village of Stonemaul, and her eggs are said to lie hidden in the cave. Anyone who nears them will meet her wrath."} },
  [269] = { name = "Opening of the Dark Portal", raid = false, levels = {68,70,68}, picture = "CAVERNSOFTIME", where = {"Tanaris",57.1,63.1} },
  [289] = { name = "Scholomance", raid = false, levels = {58,60,55}, picture = "SCHOLOMANCE", where = {"Western Plaguelands",69.0,72.7}, quests = {{-1,"Blessed Arcanite Barding","A","Ancient Equine Spirit","Dire Maul","Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",7644},{-1,"Judgment and Redemption","A","Lord Grayson Shadowbreaker","Stormwind City","Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.",7647},{58,"Healthy Dragon Scale","","Healthy Dragon Scale (an item)","","Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.",5582},{58,"Plagued Hatchlings","","Betina Bigglezink","Eastern Plaguelands","Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.",5529},{60,"Barov Family Fortune","A","Weldon Barov","Western Plaguelands","Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.",5343},{60,"Barov Family Fortune","H","Alexi Barov","Tirisfal Glades","Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",5341},{60,"Betina Bigglezink","","Leonid Barthalomew the Revered","Eastern Plaguelands","Bring the Frozen Eggs to Betina Bigglezink.",5531},{60,"Dawn's Gambit","","Betina Bigglezink","Eastern Plaguelands","Place Dawn's Gambit in the Viewing Room of the Scholomance.  Defeat Vectus, then return to Betina Bigglezink.",4771},{60,"Doctor Theolen Krastinov, the Butcher","","Eva Sarkhoff","Western Plaguelands","Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.",5382},{60,"Kirtonos the Herald","","Eva Sarkhoff","Western Plaguelands","Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\n\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.",5384},{60,"Krastinov's Bag of Horrors","","Eva Sarkhoff","Western Plaguelands","Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",5515},{60,"The Left Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",8969},{60,"The Lich, Ras Frostwhisper","","Magistrate Marduke","Western Plaguelands","Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",5466},{60,"The Right Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",8992}}, stories = {["darkmaster gandling"]="Darkmaster Gandling is a human necromancer and the headmaster of the School of Necromancy at Caer Darrow. Kel'Thuzad appointed him personally, and he took the post after Araj the Summoner, who had led the school before him.\n\nGandling is mortal, unlike Ras Frostwhisper, the lich who rules the site and guards it for the Scourge. The Cult of the Damned uses the school to train its mortal agents, and Gandling runs it. He greets those who intrude on his study by announcing that school is in session.",["doctor theolen krastinov"]="Doctor Theolen Krastinov, known as the Butcher, is a human torturer and the servant of Kirtonos the Herald. He is the main provider of bodies and body parts for the necromancy experiments of Scholomance.\n\nHis first victims came from the household of Caer Darrow, among them the Barov servants Eva and Lucien Sarkhoff. For months he kept them trapped, tortured and maimed, used them in countless experiments to devise a plague, and held them to life by magic so that they could not die. Their ghosts remember him only as the Butcher, and they have sworn to take revenge on him, even beyond the grave.",["instructor malicia"]="Instructor Malicia is a high elf who teaches in Scholomance, the school of necromancy beneath Caer Darrow. She keeps to the Coven, a chamber deep inside the school where she and a few other warlocks and witches work.",["jandice barov"]="Jandice Barov was the daughter of Lord Alexei and Lady Illucia Barov, and an archmage of great skill. When her family gave its home to Kel'Thuzad and the Cult of the Damned, she was turned into a ghost within the school of necromancy that grew beneath Caer Darrow.\n\nIt is said that she carried the blood of innocents from Doctor Krastinov to Kirtonos the Herald. She waits in the lower halls of Scholomance, and when she is threatened she scatters copies of herself through the room, so that anyone who comes for her cannot tell which image is real.",["kirtonos"]="Kirtonos the Herald is an undead creature that can change shape between a gargoyle and a vampire. He is the master of Doctor Theolen Krastinov, and he fed on the blood of the innocent victims who passed through the doctor's hands. To keep his master content, Krastinov had to bring him more and more blood.\n\nKirtonos rarely visits Scholomance now. Blood of the innocent is hard to find around Caer Darrow, because most of its people are dead, and only ghosts remain. They spend their time plotting his destruction. A drop of blood laid on the brazier in the Chamber of Summoning still draws him in through the window.",["kormok"]="Kormok was an ogre with two heads. One was cheerful and a little foolish, and the other was sly and calculating, with an almost dead look in its eyes. He began as a mage and a decent enough member of the Veiled Blade, the mercenary company that stole the spellbook of Lord Valthalak in Blackrock Spire. Kormok grabbed the amulet Valthalak wore, and the quarrel over it broke the company apart.\n\nThen he was exposed to necromancy, and he came to delight in summoning the souls of the banished dead of Purgation Isle. He left the company for Scholomance, but Valthalak's spectral assassins found him there and killed him in front of his master, Ras Frostwhisper.",["lady illucia barov"]="Lady Illucia Barov was the wife of Lord Alexei and the mother of Jandice, Alexi and Weldon. When the Barovs gave their ground to Kel'Thuzad for his Cult of the Damned, he granted them immortality through undeath in return. Illucia now walks the school that was once her home as a ghost, and she dwells in the Shadow Vault.",["lord alexei barov"]="Lord Alexei Barov once ruled Caer Darrow, Brill, Tarren Mill and Southshore. He was the husband of Lady Illucia and the father of Alexi, Weldon and Jandice. Not content with their enormous holdings, the Barovs made a deal with the necromancer Kel'Thuzad, leader of the Cult of the Damned, and gave him their home. It became Scholomance, a school of necromancy beneath Caer Darrow, and Alexei was raised as an undead death knight in the service of the Scourge.\n\nHe still keeps the Barov Family Vault, the burial place of his line, and he guards the Deed to Caer Darrow, which his sons Alexi and Weldon both want so that they can inherit the family's wealth.",["lorekeeper polkelt"]="Lorekeeper Polkelt was once the keeper of knowledge in Scholomance. That knowledge has been lost, and he is now a shambling, unintelligent zombie. He presides over the Hall of Secrets, where a crowd of zombies spreads sickness among all who come near.",["marduk blackpool"]="Marduk Blackpool, also called Marduk the Black, was a brutal death knight and warlord of the Scourge. During the Third War he cut through the human defenders of Lordaeron with a foul, rune-covered sword. At the Battle of Darrowshire he corrupted the spirit of Joseph Redpath, and with the help of Redpath's twisted ghost the Scourge overran the town and killed everyone in it.\n\nMarduk survived the war and kept serving the Scourge. Near Corin's Crossing a dwarf captain broke his sword on an enchanted shield, and Marduk fled the field. The blade sank into the earth and ate out the gorge now known as the Infectis Scar. Afterward he came to Scholomance and became a tutor there, working beside Vectus and his plagued dragons.",["ras frostwhisperer"]="Ras Frostwhisper was a human mage who spent years among the ruins of Stromgarde before he gave himself to the Scourge. In Stratholme he pledged his undying soul to the Lich King. He stepped inside a pentagram, drew a dagger across his own throat and smiled while he did it. The Lich King stood over the body and with a single gesture raised him as a lich. Leonid Barthalomew, now of the Argent Dawn, watched it happen, and the ground there is bitterly cold to this day.\n\nRas now rules over Scholomance and guards it in the name of the Scourge, while the mortal necromancer Darkmaster Gandling serves as the school's headmaster.",["rattlegore"]="Rattlegore is a golem of bone, one of the bone golems that haunt the halls of Scholomance. He lurks in a chamber directly beneath the Great Ossuary, the room where the plagued dragon whelps are kept, close to the dungeon of Jandice Barov.",["the ravenian"]="The Ravenian is a wight, and one of the mightiest agents of Kel'Thuzad. He lives in the recesses of Scholomance, in a vault filled with water, and he is always ready to devour any student who shows a sign of weakness.",["vectus"]="Vectus is a skeletal mage and one of the main teachers of necromancy in Scholomance. He created the plagued dragons that hatch beneath the school and leads a team of Scourge scholars who study them. The eggs come from Tinkee Steamboil, a goblin scholar in the Burning Steppes, who delivers dragon eggs from Blackrock Spire.\n\nVectus tells his students that the young dragons thrive on terrified flesh, and that their dragonflight will soon be ready to serve the Lich King's plans."} },
  [309] = { name = "Zul'Gurub", raid = true, levels = {57,63,56}, picture = "ZulGurub", where = {"Stranglethorn Vale",54.2,17.6}, quests = {{60,"Animist's Caress","","Zanza the Restless","Zul'Gurub","",8192},{60,"Death's Embrace","","Zanza the Restless","Zul'Gurub","",8186},{60,"Enchanted South Seas Kelp","","Maywiki of Zuldazar","Stranglethorn Vale","",8110},{60,"Enchanted South Seas Kelp","","Maywiki of Zuldazar","Stranglethorn Vale","",8111},{60,"Enchanted South Seas Kelp","","Maywiki of Zuldazar","Stranglethorn Vale","",8112},{60,"Falcon's Call","","Zanza the Restless","Zul'Gurub","",8187},{60,"Hoodoo Hex","","Zanza the Restless","Zul'Gurub","",8190},{60,"Kezan's Taint","","Al'tabim the All-Seeing","Stranglethorn Vale","",8106},{60,"Kezan's Taint","","Al'tabim the All-Seeing","Stranglethorn Vale","",8107},{60,"Kezan's Taint","","Al'tabim the All-Seeing","Stranglethorn Vale","",8108},{60,"Kezan's Unstoppable Taint","","Al'tabim the All-Seeing","Stranglethorn Vale","",8109},{60,"Maelstrom's Wrath","","Falthir the Sightless","Stranglethorn Vale","",8148},{60,"Presence of Might","","Zanza the Restless","Zul'Gurub","",8184},{60,"Presence of Sight","","Zanza the Restless","Zul'Gurub","",8189},{60,"Pristine Enchanted South Seas Kelp","","Maywiki of Zuldazar","Stranglethorn Vale","",8113},{60,"Prophetic Aura","","Zanza the Restless","Zul'Gurub","",8191},{60,"Strength of Mount Mugamba","","Jin'rokh the Breaker","Stranglethorn Vale","",8041},{60,"Strength of Mount Mugamba","","Jin'rokh the Breaker","Stranglethorn Vale","",8042},{60,"Strength of Mount Mugamba","","Jin'rokh the Breaker","Stranglethorn Vale","",8043},{60,"Syncretist's Sigil","","Zanza the Restless","Zul'Gurub","",8185},{60,"The All-Seeing Eye of Zuldazar","","Al'tabim the All-Seeing","Stranglethorn Vale","",8052},{60,"The Eye of Zuldazar","","Al'tabim the All-Seeing","Stranglethorn Vale","",8049},{60,"The Eye of Zuldazar","","Al'tabim the All-Seeing","Stranglethorn Vale","",8050},{60,"The Eye of Zuldazar","","Al'tabim the All-Seeing","Stranglethorn Vale","",8051},{60,"The Heathen's Brand","","Jin'rokh the Breaker","Stranglethorn Vale","",8045},{60,"The Heathen's Brand","","Jin'rokh the Breaker","Stranglethorn Vale","",8046},{60,"The Heathen's Brand","","Jin'rokh the Breaker","Stranglethorn Vale","",8047},{60,"The Hero's Brand","","Jin'rokh the Breaker","Stranglethorn Vale","",8048},{60,"The Jewel of Kajaro","","Al'tabim the All-Seeing","Stranglethorn Vale","",8104},{60,"The Maelstrom's Tendril","","Falthir the Sightless","Stranglethorn Vale","",8145},{60,"The Maelstrom's Tendril","","Falthir the Sightless","Stranglethorn Vale","",8146},{60,"The Maelstrom's Tendril","","Falthir the Sightless","Stranglethorn Vale","",8147},{60,"The Pebble of Kajaro","","Al'tabim the All-Seeing","Stranglethorn Vale","",8101},{60,"The Pebble of Kajaro","","Al'tabim the All-Seeing","Stranglethorn Vale","",8102},{60,"The Pebble of Kajaro","","Al'tabim the All-Seeing","Stranglethorn Vale","",8103},{60,"The Perfect Poison","","Dirk Thunderwood","Silithus","Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.",9023},{60,"The Rage of Mugamba","","Jin'rokh the Breaker","Stranglethorn Vale","",8044},{60,"The Savage Guard - Arcanum of Focus","","Zanza the Restless","Zul'Gurub","Zanza the Restless in Zul'Gurub wants an Arcanum of Focus.",9210},{60,"The Savage Guard - Arcanum of Protection","","Zanza the Restless","Zul'Gurub","Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.",9208},{60,"The Savage Guard - Arcanum of Rapidity","","Zanza the Restless","Zul'Gurub","Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.",9209},{60,"The Unmarred Vision of Voodress","","Maywiki of Zuldazar","Stranglethorn Vale","",8119},{60,"Vision of Voodress","","Maywiki of Zuldazar","Stranglethorn Vale","",8116},{60,"Vision of Voodress","","Maywiki of Zuldazar","Stranglethorn Vale","",8117},{60,"Vision of Voodress","","Maywiki of Zuldazar","Stranglethorn Vale","",8118},{60,"Vodouisant's Vigilant Embrace","","Zanza the Restless","Zul'Gurub","",8188},{60,"Zandalarian Shadow Mastery Talisman","","Falthir the Sightless","Stranglethorn Vale","",8144},{60,"Zandalarian Shadow Talisman","","Falthir the Sightless","Stranglethorn Vale","",8141},{60,"Zandalarian Shadow Talisman","","Falthir the Sightless","Stranglethorn Vale","",8142},{60,"Zandalarian Shadow Talisman","","Falthir the Sightless","Stranglethorn Vale","",8143}}, stories = {["bloodlord mandokir"]="Bloodlord Mandokir is a jungle troll and one of the most powerful lieutenants of Hakkar the Soulflayer. He leads the Gurubashi, the strongest troll tribe, who dwell in the ancient city of Zul'Gurub.\n\nWhen Hakkar was to be summoned into the mortal world, Mandokir and his people were reluctant and rose up against the plan. Once the blood god entered the world, their resistance ended, and they soon carried out his every command. Mandokir is rarely seen without Ohgan, the raptor he rides, and the two fight side by side.",["edge of madness"]="In a corner of the old city, tablets line the walls around a brazier, and from that place one of four troll spirits can be roused. All four are ghosts, and each carries a different kind of rage.\n\nGri'lek was a dire troll berserker. Long ago he turned his ear from the spirits and lost his right arm, and he wandered the jungle with his eyes burning, roaring his curses at a sky that no longer listened. Renataki, of the Thousand Blades, lives on pain and fear and hopes to return one day with bloodshed. Hazza'rah, a troll turned ghost, conjures illusions to torment the living. Wushoolay, a jungle troll, wields the lightning.",["gahzranka"]="Gahz'ranka is a giant hydra that lives in the waters of the ancient Gurubashi capital of Zul'Gurub. The famous fisherman Nat Pagle hunted the creature for a long time and never landed it. He left only a ruined camp at the shore, with shattered lures and tackle, and a measuring tape he lost there.",["hakkar"]="Hakkar the Soulflayer is the blood god of the trolls, a vile and bloodthirsty spirit. Some 1,500 years before the Dark Portal opened, famine and terror ruled the broken troll kingdoms. The Gurubashi called on ancient forces for aid, and Hakkar answered. He gave them the secrets of blood and helped them spread their civilization across most of Stranglethorn Vale. But he wanted ever more, and demanded that souls be sacrificed to him every day.\n\nThe other trolls turned against him. Gurubashi and Zandalari rose together in a war that shattered the young empire, destroyed Hakkar's avatar and drove his priests, the Atal'ai, from Zul'Gurub. The exiles fled north to the Swamp of Sorrows and raised a temple to him there, until the dragon Aspect Ysera smashed it beneath the marsh.\n\nIn time the Atal'ai learned that Hakkar could take physical form only in Zul'Gurub. Their prophet Jammal'an promised them immortality, and their priests succeeded. Now the Soulflayer sits in the heart of the ruins and has enslaved five high priests of the trolls' gods, who feed him their power.",["high priest thekal"]="High Priest Thekal serves Shirvallah, the tiger god. When the blood god Hakkar was called into Zul'Gurub, the trolls of the land sent five high priests to quell him, and Thekal was among them. Each was a champion of a primal god, but Thekal fell under Hakkar's sway like the others.\n\nNow he channels Shirvallah's power into the Soulflayer. Two zealots, Lor'Khan and Zath, stand beside him, and tigers attend him.",["high priest venoxis"]="High Priest Venoxis is the Zandalari priest of Hethiss, the snake god. He was one of five high priests sent into Zul'Gurub to quell Hakkar the Soulflayer, and like the others he fell under the blood god's sway.\n\nNow Venoxis channels the power of his own god into Hakkar, and the serpent god is weakened as the blood god swells. He is attended by Razzashi cobras, and when his rage runs high he takes the shape of a great snake.",["high priestess arlokk"]="High Priestess Arlokk serves Bethekk, the panther goddess. She was one of five high priests sent into Zul'Gurub to quell Hakkar the Soulflayer, and she, too, fell under his sway.\n\nArlokk now feeds the power of Bethekk to the blood god. Her temple is full of panthers, and she herself takes the form of a great cat, a hunter that moves unseen until she is ready to strike.",["high priestess jeklik"]="High Priestess Jeklik serves the bat god Hir'eek, one of the primal gods of the trolls. When Hakkar the Soulflayer was called into Zul'Gurub, the trolls of the land banded together and sent a contingent of high priests into the ancient city to quell him. Each was a powerful champion of a god, but despite their efforts they fell under Hakkar's sway.\n\nJeklik is one of the five. She takes the shape of a great bat, and she is forced to channel the power of her god into the blood god, who grows stronger while Hir'eek is drained.",["high priestess marli"]="High Priestess Mar'li serves Shadra, the spider god, and was one of the five high priests the trolls sent into Zul'Gurub against Hakkar the Soulflayer. Each of them was a powerful champion of a primal god, yet all fell under Hakkar's sway.\n\nMar'li now feeds the power of Shadra into the blood god. In her lair she hatches broods of spiders, and she changes into the form of a great spider herself.",["jindo the hexxer"]="Jin'do the Hexxer is a jungle troll witch doctor and the leader of the Hakkari. His tribe was exiled or murdered for the evil deeds it did in Hakkar's name, and the survivors resolved to wreak havoc on the world and bring the blood god into it.\n\nJin'do is one of Hakkar's most powerful lieutenants. In Zul'Gurub he has enslaved several high priests of the Gurubashi to help him summon their dread god, and he and the remaining Hakkari now live inside the walls of the ancient capital."} },
  [329] = { name = "Stratholme", raid = false, levels = {58,60,55}, picture = "STRATHOLME", where = {"Eastern Plaguelands",44.0,17.4}, quests = {{60,"Above and Beyond","","Duke Nicholas Zverenhoff","Eastern Plaguelands","Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.",5263},{60,"Aurius' Reckoning","","Aurius","Stratholme","",5125},{60,"Dead Man's Plea","","Anthion Harmon","Stratholme","Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.",8945},{60,"Houses of the Holy","","Leonid Barthalomew the Revered","Eastern Plaguelands","Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",5243},{60,"Menethil's Gift","","Leonid Barthalomew the Revered","Eastern Plaguelands","Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.",5463},{60,"Of Love and Family","","Artist Renfray","Western Plaguelands","Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\n\nReturn the painting to Tirion Fordring.",5848},{60,"Ramstein","H","Nathanos Blightcaller","Eastern Plaguelands","Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",6163},{60,"The Active Agent","","Betina Bigglezink","Eastern Plaguelands","Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.",5213},{60,"The Archivist","","Duke Nicholas Zverenhoff","Eastern Plaguelands","Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.",5251},{60,"The Flesh Does Not Lie","","Betina Bigglezink","Eastern Plaguelands","Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.",5212},{60,"The Great Fras Siabi","","Smokey LaRue","Eastern Plaguelands","Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.",5214},{60,"The Left Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",8968},{60,"The Medallion of Faith","","Aurius","Stratholme","",5122},{60,"The Restless Souls","","Egan","Eastern Plaguelands","Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\n\nFree 15 Restless Souls and return to Egan.",5282},{60,"The Right Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",8991},{60,"The Truth Comes Crashing Down","","Head of Balnazzar (an item)","","Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.",5262}}, stories = {["archivist galford"]="Galford is the archivist of the Scarlet Crusade in Stratholme and takes great pride in his charge, the Crusade's most valued documents. He keeps them in the Scarlet Archive in the last corridor of the Scarlet Bastion.\n\nThe archive holds years of intelligence. Duke Nicholas Zverenhoff of the Argent Dawn sees it as a prize worth burning, certain that its loss would hurt the zealots for weeks to come.",["balnazzar"]="Balnazzar is a nathrezim dreadlord, one of three brothers left behind in Lordaeron to oversee the demonic conquest of that land. When Arthas returned from Kalimdor the brothers scattered, then plotted against him and failed. Sylvanas Windrunner later besieged Balnazzar's stronghold in the ruined capital and ordered his brother Varimathras to kill him, and the dreadlord was thought destroyed.\n\nHe lived. Wearing the face of Saidan Dathrohan, one of the first paladins of the Silver Hand, he became Grand Crusader of the Scarlet Crusade, and its zealots follow him without knowing what he is. They are his unwitting pawns.\n\nBalnazzar has never tasted true death, though he has known defeat. He sits in the Scarlet Bastion of Stratholme and plots vengeance.",["baron rivendare"]="Baron Rivendare was a wealthy landowner in Stratholme who fell under the sway of Kel'Thuzad. He helped build the Cult of the Damned, and by the time of the Third War he was known as the Master of Stratholme. In the end the plague corrupted him completely, and he took the title and powers of a death knight.\n\nHe now rules the Scourge half of the burning city from the Slaughterhouse. He rides an unholy skeletal steed, Deathcharger, and the skeletons of the Black Guard are his elite. He holds Stratholme against the Scarlet Crusade, coordinates the Lich King's efforts across the Plaguelands, and serves Kel'Thuzad eagerly. He fights the agents the Argent Dawn sends against him under Duke Nicholas Zverenhoff, and he holds one of them, Ysida Harmon, prisoner. One of his greatest joys is corrupting paladins.",["baroness anastari"]="In life Baroness Anastari took what she wanted, no matter the cost. The Scourge murdered her brutally, tore her soul from her body and bound her to the Lich King as a banshee.\n\nThe grave changed little about her. She gave up her love of material trinkets for possessions of a far more sinister kind. She guards one of the ziggurats in Stratholme that stand before the Slaughterhouse, and she can seize any living creature she touches, driving out its soul and wearing the body as her own for a time.",["black guard swordsmith"]="The Swordsmith is an armored skeleton of the Black Guard, the elite corps of skeletal warriors that serves Baron Rivendare on the Scourge side of Stratholme.\n\nThe Black Guard stole the plans of the sword Corruption, and the Swordsmith watches over them near the ziggurat of Baroness Anastari. He tells any thief that payment for those plans comes in bones.",["cannon master willey"]="Cannon Master Willey is a ranking member of the Scarlet Crusade, which holds the western half of Stratholme under Grand Crusader Dathrohan. His post is the Hoard, a hall in the Scarlet Bastion where the Crusade keeps its stash of weaponry, and he presides over it. The hall dead-ends in a row of cannons.",["crimson hammersmith"]="The Crimson Hammersmith is a human smith in the service of the Scarlet Crusade, working inside the Scarlet Bastion in Stratholme. He guards the secrets of the hammersmith's craft with his life and will let no one take them.",["ezra grimm"]="Ezra Grimm owned and ran Ezra Grimm's Premium Tobacco, a smoke shop in Stratholme. When the Scourge invaded during the Third War he refused to abandon his shop. He fought to make sure the undead would never touch his famous tobacco, and became one of them in the process.\n\nHe is still in Stratholme, still guarding his stock, and he turns on anyone who tries to salvage the tobacco.",["hearthsinger forresten"]="Forresten was a traveling singer and piccolo player who was in Stratholme when Prince Arthas ordered the city purged. The Culling claimed countless people whose only crime was being inside its walls, and the musician was one of them.\n\nHe still wanders the streets of Stratholme as a ghost, unable to accept what happened to him.",["magistrate barthilas"]="Barthilas began as an ambitious young paladin at Mardenholde Keep, second to Lord Tirion Fordring. The Second War had taken his parents and left him with a deep hatred of orcs. When Tirion defended the orc Eitrigg, Barthilas moved to capture the prisoner and oversaw his master's prosecution. During Thrall's raid on Stratholme an orc drove a spear into his chest, yet he survived, took over Mardenholde after Tirion's exile, and in time became Magistrate of Stratholme.\n\nArthas's purge killed him along with the people he governed. The Lich King later raised him from the grave as a wight, a hulking undead brute, and ordered him to guard his ruined home.",["maleki the pallid"]="Maleki was among the first to join the Cult of the Damned. A mortal human mage, he showed a tremendous aptitude for the chill of the grave and for frost and shadow magic.\n\nHe is driven by an insatiable desire for power and spends his days sharpening his skill in the dark arts, preparing for the moment he will be remade as a lich. He guards one of the ziggurats before the Slaughterhouse in Stratholme.",["malor the zealous"]="Malor is a paladin of the Scarlet Crusade, the zealous order that rose from the Knights of the Silver Hand after the Third War. The Crusade holds the western half of Stratholme from the Scarlet Bastion, once the Bastion of the Silver Hand, and Malor is a crazed member of the order.\n\nHe keeps to a chamber off the Hall of Lights, deep inside the Bastion, where he guards the Medallion of Faith. A paladin sheltering in Alonsus Chapel believes the medallion would give him the strength to resist the corruption in his heart and leave.",["nerubenkan"]="Nerub'enkan was a fearsome nerubian warrior who fought the Scourge in the war that broke her people. She succumbed to her wounds and was raised into undeath as an obedient crypt fiend in the Lich King's service.\n\nShe now guards a ziggurat in the Gauntlet of Stratholme, one of three that bar the way to the Slaughterhouse and Baron Rivendare, and she defends it as fiercely as she once defended her home.",["postmaster malown"]="Malown was the Postmaster of Stratholme, and he did not hold the post by neglecting the mail. When the Scourge attacked he could not escape their masses. In death he is still dedicated to the stability of the postal system, and he haunts the city to make sure nobody tampers with the mail. He has sworn that not even hail, sleet or snow will stop him, and should the system be disrupted to the point of threatening instability, he may take matters into his own hands.",["ramstein the gorger"]="Ramstein is one of the Scourge's most infamous abominations, a horror stitched together from many corpses and driven by a ceaseless hunger. He is dim-witted, yet fearless and tenacious, and he can press a fight for hours without growing weary.\n\nWhen Scourge forces overran Stratholme he committed unspeakable atrocities on countless innocents, and thousands died by his hands, among them the ranger lord Nathanos Marris. Marris now serves the Forsaken as Nathanos Blightcaller. He hunted Ramstein across the Plaguelands for months, until the abomination fled to the safety of Stratholme.",["the unforgiven"]="Lylia was a blade of righteousness among her people. When Arthas commanded his forces to purge Stratholme, she watched countless innocents die by her hand, and the sight tore her sanity apart. She fell on her sword to escape the madness around her.\n\nDying gave her no peace. She now haunts Market Row as a spectral being, forever denied absolution for what she did.",["timmy the cruel"]="Timmison was a champion infamous for his savagery on the field of battle. His sadism may have grown out of the bullying he suffered as a child.\n\nThe Scourge raised him as a ghoul with a shattered mind. The old torment is still with him, and he answers to the name he once loathed, Timmy. He lurks just outside the courtyard of the Scarlet Bastion."} },
  [349] = { name = "Maraudon", raid = false, levels = {41,48,39}, picture = "MARAUDON", where = {"Desolace",35.9,64.6}, quests = {{42,"Shadowshard Fragments","A","Archmage Tervosh","Dustwallow Marsh","Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",7070},{42,"Shadowshard Fragments","H","Uthel'nay","Orgrimmar","Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",7068},{47,"Twisted Evils","","Willow","Desolace","Collect 15 Theradric Crystal Carvings for Willow in Desolace.",7028},{47,"Vyletongue Corruption","A","Talendria","Desolace","Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.",7041},{47,"Vyletongue Corruption","H","Vark Battlescar","Desolace","Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.",7029},{48,"The Pariah's Instructions","","Centaur Pariah","Desolace","Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.",7067},{49,"Legends of Maraudon","","Cavindra","Maraudon","Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\n\nFind a way to speak with Celebras.",7044},{49,"The Scepter of Celebras","","Celebras the Redeemed","","Assist Celebras the Redeemed while he creates the Scepter of Celebras.\n\nSpeak with him when the ritual is complete.",7046},{51,"Corruption of Earth and Seed","A","Keeper Marandis","Desolace","Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.",7065},{51,"Corruption of Earth and Seed","H","Selendra","Desolace","Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",7064},{51,"Seed of Life","","Zaetar's Spirit","","Seek out Remulos in Moonglade and give him the Seed of Life.",7066}}, stories = {["celebras the cursed"]="Celebras is the son of Remulos and a keeper of the grove, like his father. When his uncle Zaetar was killed by his own centaur children and his spirit was held captive in Maraudon, Celebras and his dryad sisters swore to free it.\n\nThe keeper was not prepared for the horrors in Maraudon's shadowy corridors. The corruption that had spread through the caverns overcame him and filled his heart with uncontrollable rage. Now he wanders blindly through the caves, cursed, while Vyletongue and Noxxion hold the two halves of his broken scepter.",["landslide"]="For years the ancient mountain giant Landslide cultivated brilliant crystal gardens in the caverns of Maraudon, before Theradras made her home there.\n\nWhen the princess took up residence, she enthralled the behemoth. The once-stoic giant now lives only to serve his tyrannical new master.",["lord vyletongue"]="Lord Vyletongue leads the Putridus clan of satyrs. He journeyed into the depths of Maraudon after hearing of its corruption. Princess Theradras was wary of the conniving satyr at first, but he proved his worth by creating a host of wretched minions for her, among them Noxxion and Razorlash.\n\nWherever he goes he spreads his evil through the twisting caves, poisoning the minds of all inside and stunting the growth of the plants.",["noxxion"]="Noxxion is a living embodiment of corruption, a putrid elemental. The satyr Lord Vyletongue made him, at the order of Princess Theradras, to be a powerful servant and a loyal pet to ease her loneliness.\n\nNoxxion spreads his toxic essence into the parts of Maraudon that have not yet withered under Theradras's malign influence.",["princess theradras"]="Theradras is an enormous earth elemental, a princess. Zaetar, a keeper of the grove and first son of Cenarius, fell in love with her despite the warnings of his brother Remulos. Their children were the first centaur, born misshapen and hateful, and they killed their father.\n\nGrief-stricken, and fearing the wrath of Cenarius, Theradras trapped her lover's spirit in the caverns the centaur named Maraudon and came to treat as holy ground. She bent the place into a den of corruption and suffering, and she guards Zaetar's remains in the crystal caverns of her inner sanctum.\n\nShe loves the centaur still. When she feared the Horde might drive them to extinction, she filled them with her power and sent them to war for new lands beyond Desolace.",["razorlash"]="Razorlash was made to accompany Noxxion through Maraudon, one of the wretched creations of the satyr Lord Vyletongue. In time it became one of the princess Theradras's most cherished servants.\n\nIt wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.",["rotgrip"]="Rumor has it that Rotgrip has dwelled in the subterranean waters of Maraudon for millennia, a giant crocolisk lurking below Zaetar's grave.\n\nThe famed dwarven hunter Hemet Nesingwary once declared that the beast could not be found, and a number of amateur trackers took up the challenge of seeking out the legendary creature. None of them ever returned.",["tinkerer gizlock"]="Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. The plan went horribly wrong when satyrs slaughtered everyone in the party but Gizlock.\n\nTrapped within the caves, the goblin was driven to the brink of madness. He now sees himself as the ruler of the whole subterranean realm, and he will not suffer anyone to reveal his presence."} },
  [389] = { name = "Ragefire Chasm", raid = false, levels = {15,16,15}, picture = "RAGEFIRECHASM", where = {"Orgrimmar",53.2,48.7}, quests = {{15,"Under the Enemy's City","A","Master Mathias Shaw","Stormwind City","Kill Taragaman the Hungerer in Ragefire Chasm, beneath Orgrimmar, then return to Master Mathias Shaw in Old Town, Stormwind.",9200045},{16,"Hidden Enemies","H","Thrall","Orgrimmar","Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",5728},{16,"Returning the Lost Satchel","H","Maur Grimtotem","Ragefire Chasm","Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",5724},{16,"Searching for the Lost Satchel","H","Rahauro","Thunder Bluff","Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",5722},{16,"Slaying the Beast","H","Neeru Fireblade","Orgrimmar","Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",5761},{16,"The Invoker and the Satyr","A","Master Mathias Shaw","Stormwind City","Kill Jergosh the Invoker and Bazzalan in Ragefire Chasm, then return to Master Mathias Shaw in Old Town, Stormwind.",9200046},{16,"The Power to Destroy...","H","Bragor Bloodfist","Undercity","Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.",14356},{16,"The Power to Destroy...","H","Varimathras","","Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",5725},{19,"Warsong Runner Update","H","Warsong Runner","Ashenvale","",6545},{21,"Warsong Scout Update","H","Warsong Scout","Ashenvale","",6547},{25,"Warsong Outrider Update","H","Warsong Outrider","Ashenvale","",6546}}, stories = {["bazzalan"]="Bazzalan is a satyr who leads the Searing Blade cultists alongside the orc warlock Jergosh. His motives are unclear. Like all satyrs he is swift and cunning, and he holds a ledge above Jergosh in the cult's hiding place beneath Orgrimmar.",["jergosh the invoker"]="Jergosh is an orc who rejected the ideals of his people and took up the dark and demonic arts of the warlock. He is one of the leaders of the Searing Blade, a sect of the Shadow Council that has taken refuge in Ragefire Chasm beneath Orgrimmar.\n\nThere he schemes, and the plot is dangerous enough to have drawn the attention of Thrall himself. Many of his cultists believe they are the next rising power among warlocks, ready to replace the Shadow Council, but only Jergosh and his fellow leaders are more than expendable.",["oggleflint"]="Oggleflint is the chief of the Ragefire troggs, who once ruled unchallenged in the depths of Ragefire Chasm beneath Orgrimmar. The Searing Blade cultists moved in, and the troggs proved too weak to drive them out.\n\nOggleflint and his troggs fell back toward the entrance, where they wait patiently for their unwelcome guests to leave. When Magatha Grimtotem sent diplomats to make peace, the troggs turned on them, and Oggleflint stands guard over the body of one of them, the tauren Maur Grimtotem.",["taragaman the hungerer"]="Taragaman is a felguard, a massive demon who stands in the middle of a lake of lava deep in Ragefire Chasm. Many believe he leads the Searing Blade, and it is said he uses his demonic influence to corrupt the citizens of Orgrimmar.\n\nIn truth the cult's leaders are Bazzalan and Jergosh. Taragaman is expendable bait, set out to lure young Horde champions to their deaths."} },
  [409] = { name = "Molten Core", raid = true, levels = {60,63,60}, picture = "MoltenCore", where = {"Burning Steppes",26.3,24.6}, quests = {{60,"Attunement to the Core","A","Lothos Riftwaker","Blackrock Mountain","Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.",7848},{60,"Attunement to the Core","H","Lothos Riftwaker","Blackrock Mountain","Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.",7487},{60,"Favor Amongst the Brotherhood, Blood of the Mountain","","Lokhtos Darkbargainer","Blackrock Depths","",6646},{60,"Favor Amongst the Brotherhood, Core Leather","","Lokhtos Darkbargainer","Blackrock Depths","",6645},{60,"Favor Amongst the Brotherhood, Dark Iron Ore","","Lokhtos Darkbargainer","Blackrock Depths","",6642},{60,"Favor Amongst the Brotherhood, Fiery Core","","Lokhtos Darkbargainer","Blackrock Depths","",6643},{60,"Favor Amongst the Brotherhood, Lava Core","","Lokhtos Darkbargainer","Blackrock Depths","",6644},{60,"Hands of the Enemy","","Duke Hydraxis","Azshara","Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.",6824},{60,"Scrying Goggles? No Problem!","","Inconspicuous Crate","","Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.",8578},{60,"The Molten Core","","Duke Hydraxis","Azshara","Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.",6822}}, stories = {["baron geddon"]="Baron Geddon is a fire elemental who followed Ragnaros out of the Firelands when Thaurissan summoned the Firelord. Long ago he fought the titans and helped betray Thunderaan, Prince of Air. Ragnaros devoured the prince's essence but could not consume all of it, so the rest was trapped in a talisman of elemental binding. Ragnaros split the talisman into two equal halves and gave one to Geddon and one to Garr.\n\nGeddon suspects that Garr wants the whole talisman and watches his old comrade closely. Rumor says Majordomo Executus took his place at the Firelord's side, and the two have been rivals since. He also taught Lord Incendius to wield fire, then grew wary of him and sent him away to guard the Dark Iron dwarves' Black Anvil.",["garr"]="Garr is a molten rock elemental and one of the two chief lieutenants of Ragnaros. He came into Azeroth with the Firelord during the War of the Three Hammers. Earlier, he helped betray Thunderaan, the Prince of Air, also called the Windseeker. Ragnaros wanted to consume the prince, and Garr and Baron Geddon ambushed him. Thunderaan was destroyed, but Ragnaros could not swallow all of his essence. He sealed the remainder in a talisman of elemental binding, split it in two and gave one half each to his lieutenants.\n\nAfter centuries of partnership, Geddon suspects that Garr wants both halves, and relations between them are strained. Garr draws strength from the blazing runes cut into the floor of the Molten Core, and eight Firesworn serve as his guard.",["gehennas"]="Gehennas was pulled out of the Elemental Plane together with the other flamewakers shortly after Thaurissan accidentally summoned Ragnaros. Flamewakers are elementals of flesh and blood, where fire elementals are beings of pure flame, and Gehennas works shadow magic.\n\nHe sits near the bottom of the Firelord's hierarchy and covets the power and station of those above him. Nobody who serves beside him trusts him, apart from his two guards, who believe they might gain if their overseer rises. He has a long quarrel with Lucifron that dates from their time in the Elemental Plane. Gehennas guards the Rune of Mohn in the Molten Core with two flamewakers.",["golemagg the incinerator"]="The molten giants are the most feared soldiers in the elemental forces of Ragnaros, and none of them can match Golemagg the Incinerator for brutality and efficiency. His power is so complete that he has cowed two core ragers, offspring of the colossal Magmadar, and keeps them as pets.\n\nMagmadar has not forgiven the insult and hates Golemagg for it. The great hound has not yet acted on that rage. Golemagg and his two ragers guard the Rune of Theri deep in the Molten Core.",["lucifron"]="Lucifron is a flamewaker, one of the elementals whose bodies are flesh and blood, unlike the fire elementals, who are pure flame. He and his kind were brought out of the Elemental Plane by Ragnaros after the Dark Iron sorcerer Thaurissan summoned the Firelord into Azeroth.\n\nAmong the flamewakers, overseers and their guards compete without pause for rank and for Ragnaros's favor. Lucifron has clashed with Gehennas many times, going back to their long confinement in the Elemental Plane, and that rivalry has followed them into the Molten Core. He now watches over Magmadar, the Firelord's favored pet, with two Flamewaker Protectors at his side. He keeps quiet and waits for any weakness in the other flamewakers.",["magmadar"]="Magmadar is a behemoth of igneous rock and roiling magma, and the origin of the core hounds that roam the halls of the Molten Core. He is the alpha male of all of them, and Ragnaros counts him among his favorite pets.\n\nThe story goes that while the Firelord was imprisoned in the Elemental Plane, he fed the remains of captured enemies to the waiting twin maws of Magmadar. The hound grew strong on this and loyal to his master, and his savage ferocity has never been matched. Lucifron and packs of hungry core hounds stand guard around him. Magmadar bears a grudge against the molten giant Golemagg, who bullied two of his offspring into serving as pets, though he has not yet acted on it.",["majordomo executus"]="Majordomo Executus stands at the top of the elemental hierarchy, just below Ragnaros. He is a flamewaker who earned that rank by proving close to invincible in the battles that raged in the Elemental Plane. Rumor says he took the place of Baron Geddon, and the two have been rivals ever since, though no one has confirmed it.\n\nRagnaros does not tolerate failure, so the lesser flamewakers, and Geddon above all, wait for Executus to slip. He is attended by flamewaker healers and elite guards. When his guard has been broken he says that he goes to summon the lord whose house this is, and that anyone who seeks an audience with the Firelord will forfeit their life.",["ragnaros"]="Ragnaros the Firelord is the Elemental Lord of fire. He ruled the Firelands of the Elemental Plane from Sulfuron Keep, which stands in the center of a vast sky of fire, and his lieutenants fought against the titans and betrayed Thunderaan, Prince of Air.\n\nAbout two hundred and fifty years ago the Dark Iron dwarves renewed the War of the Three Hammers. Sorcerer-Thane Thaurissan, losing the war, gathered seven of his most powerful allies in the Molten Core and called on the ancient powers below the world. Ragnaros burst into Azeroth, and his arrival created the volcanic wastes around Blackrock Mountain. Thaurissan and the seven died, and the surviving Dark Irons were enslaved. Later, Emperor Dagran Thaurissan ruled them for the Firelord and resented it.\n\nCut off from his own plane, Ragnaros is only a shadow of what he was. He lies at the bottom of Blackrock Mountain, looking for a way home and gathering strength to burn Azeroth. He has learned to make life from stone and plans an army of golems.",["shazzrah"]="Of all the flamewakers who followed Ragnaros into Azeroth, Shazzrah is the most talented in arcane magic. He knows that Baron Geddon suspects Garr of treachery, and he is glad of the quarrel, because he wants both halves of the Talisman of Elemental Binding for himself. He hopes to find a way to siphon its energies for his own use.\n\nRagnaros likely knew about his servant's talent for duplicity when he split the talisman and gave the halves to Geddon and Garr. Shazzrah waits and schemes in the Molten Core, in the same part of the halls where Geddon makes his rounds, and guards the Rune of Mazj.",["sulfuron harbinger"]="Sulfuron Harbinger is the herald of Ragnaros and one of the most favored of the flamewakers. His true name is not known. From the depths of the Molten Core he commands Ambassador Flamelash and the lesser flamewakers who serve in the outside world, and he answers only to Majordomo Executus.\n\nHe guards the Rune of Koro, one of the runes that empower the Firelord's servants, and four of Ragnaros's most fervent priests stand beside him. He watches Shazzrah in particular, certain that Shazzrah means to betray the Firelord. Sulfuron prepares for the day when the lord of fire claims Azeroth as his own."} },
  [429] = { name = "Dire Maul", raid = false, levels = {55,60,53}, picture = "DIREMAUL", where = {"Feralas",64.9,29.4}, quests = {{-1,"Arcane Refreshment","","Lorekeeper Lydros","Dire Maul","Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.",7463},{-1,"Blessed Arcanite Barding","A","Ancient Equine Spirit","Dire Maul","Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",7644},{-1,"Judgment and Redemption","A","Lord Grayson Shadowbreaker","Stormwind City","Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.",7647},{-1,"The Prison's Bindings","","Daio the Decrepit","Blasted Lands","Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.",7581},{57,"Camp Mojache","H","Harbinger Balthazad","Undercity","Speak with Talo Thornhoof at Camp Mojache in Feralas.",7492},{57,"Feathermoon Stronghold","A","Crier Goodman","Stormwind City","Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",7494},{57,"Lethtendris's Web","A","Latronicus Moonspear","Feralas","Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",7488},{57,"Lethtendris's Web","H","Talo Thornhoof","Feralas","Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",7489},{58,"Pusillin and the Elder Azj'Tordin","","Azj'Tordin","Feralas","Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",7441},{60,"A Broken Trap","","Broken Trap","","",1193},{60,"Anthion's Old Friend","","Anthion Harmon","Stratholme","Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.",8948},{60,"Codex of Defense","","Codex of Defense (an item)","","Return the book to its rightful owners.",7499},{60,"Elven Legends","A","Scholar Runethorn","Feralas","Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.",7482},{60,"Elven Legends","H","Sage Korolusk","Feralas","Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.",7481},{60,"Falrin's Vendetta","","Falrin Treeshaper","Dire Maul","Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.",8949},{60,"Free Knot!","","Knot Thimblejack","Dire Maul","",5525},{60,"Free Knot!","","Knot Thimblejack","Dire Maul","",7429},{60,"Frost Shock and You","","Frost Shock and You (an item)","","Return the book to its rightful owners.",7505},{60,"Garona: A Study on Stealth and Treachery","","Garona: A Study on Stealth and Treachery (an item)","","Return the book to its rightful owners.",7498},{60,"Harnessing Shadows","","Harnessing Shadows (an item)","","Return the book to its rightful owners.",7502},{60,"Holy Bologna: What the Light Won't Tell You","","Holy Bologna: What the Light Won't Tell You (an item)","","Return the book to its rightful owners.",7504},{60,"Libram of Focus","","Lorekeeper Lydros","Dire Maul","Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.",7484},{60,"Libram of Protection","","Lorekeeper Lydros","Dire Maul","Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.",7485},{60,"Libram of Rapidity","","Lorekeeper Lydros","Dire Maul","Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.",7483},{60,"The Arcanist's Cookbook","","The Arcanist's Cookbook (an item)","","Return the book to its rightful owners.",7500},{60,"The Emerald Dream...","","The Emerald Dream (an item)","","Return the book to its rightful owners.",7506},{60,"The Gordok Ogre Suit","","Knot Thimblejack","Dire Maul","",5519},{60,"The Gordok Ogre Suit","","Knot Thimblejack","Dire Maul","Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.",5518},{60,"The Instigator's Enchantment","","Falrin Treeshaper","Dire Maul","Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards.",8950},{60,"The Left Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",8967},{60,"The Light and How To Swing It","","The Light and How to Swing It (an item)","","Return the book to its rightful owners.",7501},{60,"The Madness Within","","Shen'dralar Ancient","Dire Maul","You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.",7461},{60,"The Right Piece of Lord Valthalak's Amulet","","Bodley","Blackrock Mountain","Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",8990},{60,"The Treasure of the Shen'dralar","A","Shen'dralar Ancient","Dire Maul","Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",7462},{60,"The Treasure of the Shen'dralar","H","Shen'dralar Ancient","Dire Maul","Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",7877},{60,"Unfinished Gordok Business","","Captain Kromcrush","Dire Maul","Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",1318},{60,"Unfinished Gordok Business","","Captain Kromcrush","Dire Maul","Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",7703}}, stories = {["alzzin the wildshaper"]="Legends say Alzzin was a gifted arcane illusionist and one of the first students of the satyr Lord Xavius. After the Burning Legion fell at the Battle of Mount Hyjal, he went south to Feralas to continue his masters' mission, the corruption of the forests of Kalimdor. A lone satyr armed with tricks found little success.\n\nHe found what he needed in the ruins of Eldre'Thalas, his former home. There he corrupted the Highborne Shrine of Eldretharr and the Fruit of Fertility, a vine that had once protected the city, and used its power to shape illusions of his own. Feared as the Wildshaper, he commands the enslaved ancients and draws the vitality of the forest into his lair. He seeks the total corruption of Feralas.",["captain kromcrush"]="Captain Kromcrush leads King Gordok's elite ogres and commands the fearsome guards who roam the ruins. Even among ogres he is infamous for his hair-trigger rage toward anyone who insults him or the king. He crushes dissent ruthlessly. He has still less patience for those who spread the rumor of his torrid affair with a gnoll long ago.",["chorush the observer"]="Cho'Rush the Observer is a two-headed ogre mage who serves as King Gordok's chief advisor. He does not usually take sides, but when Ulrok was rising to power it was clear that nobody could challenge him. The new king appointed Cho'Rush, believing that twin heads would make him twice as resourceful as the average ogre.\n\nCho'Rush heals and defends his king with priestly, shamanic and arcane magic. When the king falls, he is ready to turn to whoever struck the blow, and he apologizes for having fought.",["guard fengus"]="Fengus is a Gordok ogre guard. Cho'Rush the Observer once told him he was destined to meet a mate while on duty. Since then Fengus has spent almost every waking moment patrolling Gordok territory.",["guard moldar"]="Mol'dar is a zealously loyal guard among the Gordok ogres. He is convinced that King Gordok gave him a pair of enchanted gauntlets, and that they made him his people's arm wrestling champion for six years running. In truth the king threw the powerful armor away, and Mol'dar simply found it first.",["guard slipkik"]="Some might think Slip'kik is merely cautious among the Gordok ogres, but he is also lazy. He does not want to challenge King Gordok directly. Instead he tinkers with traps and old, broken magical devices, hoping one day to deliver the final blow without an ounce of risk or a drop of sweat.",["hydrospawn"]="Hydrospawn is a water elemental in the Shrine of Eldretharr, in the Warpwood Quarter of Dire Maul. When the satyr Zevrim Thornhoof set out to control the elementals of the ruins, he focused on Hydrospawn. While Zevrim performed his profane sacrifices, the elemental grew agitated and restless and struck out at the satyr's demonic minions.\n\nAs the years passed, Zevrim used the energy of his victims to whip Hydrospawn into unbridled fury. Little by little he bound the elemental's will to his own commands.",["illyanna ravenoak"]="Illyanna Ravenoak was a night elf hunter of the Shen'dralar. With her faithful companion, the bear Ferra, she served as Prince Tortheldrin's most valued hunter. Then the prince ordered her to execute her friends, and she refused.\n\nAs punishment Tortheldrin killed Illyanna and her bear. He used his demonic power to bind their spirits to their bodies, and he condemned them to remain in Dire Maul as undead protectors. The huntress and Ferra now walk the Capital Gardens, and each is a fierce enemy alone.",["immolthar"]="Immol'thar is an ancient demon, a void terror held captive in the western wing of Dire Maul. When the Well of Eternity was destroyed, the Shen'dralar lost the power and immortality it gave them, and many of the Highborne slipped into lethargy. Prince Tortheldrin ordered pylons built to raise a force field. The Shen'dralar summoned the demon into the Capital Gardens and trapped him inside it.\n\nHungry for magic, they quickly mastered siphoning his demonic energy for their spells and for their immortality. For nearly ten thousand years Immol'thar could not fight back or even move. He could only watch and wait for the day he might break free and rend the flesh of his captors.",["king gordok"]="To rule the Gordok ogres one must proclaim oneself king and destroy all who might disagree. King Gordok, then merely known as Ulrok, solidified his power by convincing a dozen of his people's strongest warriors to challenge the king at the same time. The wild melee left most of the contestants dead or wounded, and Ulrok's blade easily cut down the survivors and the battle-weary king. Gordok ogres still speak in hushed tones about the Day of Da Blood.\n\nUlrok took the title and now rules the Gordunni ogres in the Gordok Commons of Dire Maul, with Cho'Rush the Observer as his chief advisor. By tradition, whoever slays the king becomes the next King Gordok.",["lethtendris"]="Lethtendris is an elf warlock with an unbearable craving for arcane magic. The warped energy of Dire Maul drew her from afar, and she made a lair in the Warpwood Quarter, with her imp Pimgib at her side.\n\nFrom the sinews and ligaments of sacrificial victims she built a web, a device that slowly siphons the corrupt power out of the ruins. She found that it can gather vast reserves of overwhelming strength, enough to destroy all of her enemies.",["lord helnurath"]="Lord Hel'nurath is one of the nathrezim and the ruler of Xoroth, where he keeps the stables. Xoroth is one of the fiery, chaotic worlds of the Burning Legion, a place of infernal heat and scorched bones. Dreadsteeds live there, and the nathrezim ride them as mounts.\n\nHel'nurath prizes his steeds. When a warlock tears one of them out of Xoroth, as happens in the ruins of Dire Maul West, he comes through a portal in a rage. He demands to know who dares to steal his precious mount and swears the thief will pay for the insolence.",["magister kalendris"]="Magister Kalendris was one of the most loyal lieutenants of Prince Tortheldrin. When the prince demanded the slaughter of most of his subjects, Kalendris was tasked with carrying out the order. He murdered many unsuspecting Shen'dralar without hesitation.\n\nIn a destructive battle one of the doomed elves mortally wounded him. His death did not end his service. His ghost still roams the Court of the Highborne in Dire Maul West, a defender of Tortheldrin's rule.",["prince tortheldrin"]="Prince Tortheldrin was a loyal servant of Queen Azshara and the leader of the Shen'dralar, the Highborne who guarded her arcane secrets in the hidden city of Eldre'Thalas, now called Dire Maul. When the Great Sundering struck, he and his followers wove a spell that shielded the city from destruction. The Well of Eternity was gone, though, and without it their immortality faded.\n\nTo keep control of the surviving Shen'dralar he built pylons in the west wing and imprisoned the demon Immol'thar, so that his subjects could siphon the creature's strength. The demonic power twisted his mind. When the demon faltered, he ordered the deaths of many of his vassals so that only he and his most fanatical followers could enjoy the corrupt energy. Among the dead were his hunter Illyanna Ravenoak and her bear.\n\nTortheldrin still rules the halls. He welcomes visitors and trades stories with them, but he guards the secret of Immol'thar jealously, and those who meddle in his domain can expect a brutal end.",["pusillin"]="Pusillin is a mischievous imp who lives in the eastern part of Dire Maul, near the main entrance. In the hurry of his escape from the fallen Prince Tortheldrin, the Highborne elder Azj'Tordin was robbed by him. Pusillin took his book of incantations and the key to the once great halls of Eldre'Thalas.\n\nThe imp treats the theft as a game. He skips away from anyone who comes near and sings that the key is theirs if they can catch him. Whoever keeps chasing finds him less amused, and he calls his fiery friends to his side.",["stomper kreeg"]="Stomper Kreeg is a Gordok ogre who is often passed out drunk on duty. His mug of ale is precious to him. More than once a skulking assassin has met his doom after disturbing it by accident, because nothing rouses Kreeg into a berserker fury faster than the sound of his drink splattering on the stone floor.",["tendris warpwood"]="Tendris Warpwood is an ancient who stood as a staunch defender of Eldre'Thalas. His heart was bound to the fate of the city. When the Great Sundering shattered the land his resolve never wavered.\n\nOver the next ten thousand years corruption seeped into the ruins, and it infected the ancient's spirit. He now holds the Capital Gardens of Dire Maul. The Ironbark Protectors answer his call, and he keeps an Ancient Equine Spirit imprisoned in spectral bonds. He greets intruders with the cry that they do not belong there, and he calls the ancients to rise against them.",["tsuzee"]="Tsu'zee was a night elf rogue of the Shen'dralar. She is now a ghost in Dire Maul West, where she haunts the Court of the Highborne among the wraiths, banshees and ghosts of the Highborne who once lived in the city.",["zevrim thornhoof"]="Zevrim Thornhoof is a satyr warlock who holds the Warpwood Quarter of Dire Maul. He wanted to prove his worth to the Burning Legion, and he told his masters that he could enslave the formidable ancients who still roamed the ruins. His own power fell short. He turned to other living creatures for extra energy, butchering them on a sacrificial altar and harvesting their essence in their last, agonizing moments.\n\nThe energy of his victims helped him bend the water elemental Hydrospawn to his will. He also keeps Old Ironbark in his grasp, and the ancient can do nothing while Zevrim lives."} },
  [469] = { name = "Blackwing Lair", raid = true, levels = {60,63,60}, picture = "BlackwingLair", quests = {{60,"Nefarius's Corruption","","Vaelastrasz the Corrupt","Blackwing Lair","Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.",8730},{60,"Oculus Illusions","H","Myranda the Hag","Western Plaguelands","Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.",6569},{60,"Only One May Rise","","Baristolth of the Shifting Sands","Silithus","Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.",8288}}, stories = {["broodlord lashlayer"]="Broodlord Lashlayer is a large black drakonid in the service of Nefarian. He guards the Halls of Strife in Blackwing Lair and bars the way into his master's inner sanctum. The suppression rooms are his charge, where kidnapped whelps of the other dragonflights are held, corrupted and kept in check.\n\nHe does not leave this post easily. When intruders reach him, he tells them that none of their kind should be here, and that they have doomed only themselves.",["chromaggus"]="Chromaggus is a two-headed beast made by Nefarian and the dutiful protector of Blackwing Lair. He is the only drakeadon known, a four-legged dragonkin with a body like a core hound's, and he carries the powers of all five dragonflights, drawn from Nefarian's experiments with the blood of every flight.\n\nHis scales shimmer in shifting colors, and each color is tied to a power he can use. The afflictions that radiate from him have a terrible effect on their victims, who are transformed into drakonid. His name comes from the same root as chromatic, the flight his master hopes to build.",["ebonroc"]="Ebonroc is one of three powerful black drakes that guard the way to their master, Nefarian. He is a drake of the black dragonflight and patrols the semicircular ramp that leads to the upper room of the Crimson Laboratories in Blackwing Lair. Like the other two drakes and Nefarian himself, he breathes shadow flame.",["firemaw"]="Firemaw is a black drake of the black dragonflight and one of three drakes that guard the way to their master, Nefarian. He patrols the length of the first of the Crimson Laboratories, the halls of Blackwing Lair lined with Nefarian's technicians, spellbinders and warlocks. Like Ebonroc, Flamegor and Nefarian himself, he breathes shadow flame.",["flamegor"]="Flamegor is the third of the three black drakes that guard the way to Nefarian, and he keeps the upper room of the Crimson Laboratories in Blackwing Lair. He is a drake of the black dragonflight and breathes shadow flame, as his fellow drakes and their master do. Chromaggus waits in the room beyond.",["nefarian"]="Nefarian is the son of the black Aspect Neltharion, whom the world calls Deathwing, and the brother of Onyxia. He wears a human guise as Victor Nefarius, Lord of Blackrock. The Blackrock clan and several clans of ogres answer to him, and he rules from his lair at the top of Blackrock Spire.\n\nAfter the Second War he reached out to the Dark Horde in Blackrock Mountain and struck a bargain with Rend Blackhand, then manipulated the orcs into letting the black dragonflight use the mountain as its base. He set up a hidden laboratory in the upper spire, where he works to rebuild his flight and finish what his father failed to do. He experiments with the blood of every dragonflight, much of it taken from living dragons, to breed a chromatic flight of unstoppable warriors and unspeakable hybrids.\n\nThe dwarves hold the mountain's volcanic depths under Ragnaros, and Nefarian has vowed to crush them and claim all of Blackrock Mountain. The red dragonflight has marked him, and he has enslaved Vaelastrasz.",["razorgore the untamed"]="Razorgore the Untamed is a dragonspawn of the black dragonflight, the most powerful known to the world, and by his own nature he serves no master. Nefarian found a way around that. He made an Orb of Domination that lets the Blackrock clan bend Razorgore to its will, and Grethok the Controller holds it.\n\nRazorgore guards the clutch of black dragon eggs in the first chamber of Blackwing Lair, which Nefarian values highly. He commands a garrison of orcs and dragonspawn. He will stop at nothing to protect the eggs. When he breaks free of the orb, he cries that the device will never torment him again.",["vaelastrasz the corrupt"]="Vaelastrasz, called Vaelan in his visage form, is a dragon of the red dragonflight. He kept his flight's shard of the Scepter of the Shifting Sands for nearly a thousand years, after Fandral Staghelm shattered the scepter in his grief. He saw Nefarian and the black dragonflight as a great danger to Azeroth and swore to hunt them to the end of his days.\n\nHe went into Blackwing Lair alone. There Nefarian, in his human guise as Lord Victor Nefarius, drained his strength, bent him to his will and took the shard. Nefarius threatens to destroy it. Vaelastrasz now serves unwillingly and swings between threats and pleas for forgiveness. He cries out that a black fire rages in his heart and begs Alexstrasza to help him resist."} },
  [509] = { name = "Ruins of Ahn'Qiraj", raid = true, levels = {60,63,60}, picture = "AQRuins", quests = {{60,"The Fall of Ossirian","","Head of Ossirian the Unscarred (an item)","","Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.",8791},{60,"The Perfect Poison","","Dirk Thunderwood","Silithus","Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.",9023}}, stories = {["ayamiss the hunter"]="Ayamiss the Hunter is a silithid wasp and a powerful flying hunter in the army of the qiraji. Ayamiss and the soldiers of the swarm hover high above the ground in the Comb, a part of the ruins of Ahn'Qiraj between the Hatchery and the Watchers' Terrace. Anyone who confronts the swarm may be taken and sacrificed on an altar, and Ayamiss takes great pleasure in this.",["buru the gorger"]="Buru the Gorger is a silithid colossus, a huge creature with four legs, scythe-like arms, gouging horns and a thick armored shell. He lives in the Hatchery of the Hive'Zara hive within the ruins of Ahn'Qiraj, where he guards the eggs of the qiraji. A hatchling of the hive emerges from each egg that breaks. Buru can be weakened only by the destruction of those eggs, and only then can anything break through his immensely thick armor.",["general rajaxx"]="General Rajaxx is the chief military commander of the qiraji. In the War of the Shifting Sands he was a towering monstrosity who swung clawed limbs and shouted orders to the qiraji and silithid soldiers. He fought the night elf armies.\n\nRajaxx now commands the army that gathers once more in Ahn'Qiraj. He holds the General's Terrace with his captains and majors, and he vows that a thousand years of injustice will end and that the dragons themselves will tremble.",["kurinnaxx"]="Kurinnaxx is a large sand reaver, a silithid that looks something like a solifuge. He belongs to Hive'Zara, one of the major silithid hives, and serves the qiraji and their master, C'Thun, in the ruins of Ahn'Qiraj.\n\nHe is among the first guardians a visitor meets in the ruins. The poisoners of Ravenholdt name him as one of two particularly venomous creatures, and they want his venom sac, along with the one belonging to Venoxis of Zul'Gurub, to brew a new and more effective poison.",["moam"]="During the War of the Shifting Sands, the dragons Arygos, Merithra of the Dream and Caelestrasz gave themselves to help make the Scarab Wall. The wall held the qiraji in, yet the empire did not sit idle. The dark master of Ahn'Qiraj ordered Emperor Vek'lor to build an obsidian destroyer greater than the rest. His twin Vek'nilash shaped a body of volcanic rock and Vek'lor strengthened it with magic. Vek'lor named it Moam, and the dark master gave it life.\n\nMoam proved more versatile than earlier destroyers and could summon burning elementals of pure mana. Vek'lor then learned the source of that power. The three dragons had never been granted death. Held alive in Ahn'Qiraj, they had their magic drained and corrupted to feed Moam and the master's other creations.",["ossirian the unscarred"]="In the War of the Shifting Sands, as the bronze dragonflight broke the anubisath constructs, one anubisath found a way to fight back. He hurled his obsidian sword through the wing of the great dragon Grakkarond, who fell and crushed qiraji as he came down. The dragon mauled the anubisath nearly to death before the rest overwhelmed it.\n\nOssirian was dragged back to Ahn'Qiraj and should have died, but the malevolent power that rules the qiraji spared him. He awoke stronger, his head bound in the visage of a hawk. Emperor Vek'nilash told him he had succeeded where all others, General Rajaxx included, had failed. Ancient crystals now bind his essence and make him nearly invulnerable, though he dies if he strays far from them. His kind revere him as the Unscarred."} },
  [531] = { name = "Ahn'Qiraj Temple", raid = true, levels = {60,63,60}, picture = "AQTemple", where = {"Silithus",15.3,97.8}, quests = {{60,"Atiesh, the Befouled Greatstaff","","Anachronos","Tanaris","Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.",9251},{60,"Avenger's Breastplate","","Vethsera","Ahn'Qiraj","Bring the the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",8627},{60,"Avenger's Crown","","Andorgos","Ahn'Qiraj","Bring Vek'lor's Diadem, 2 Idols of Rebirth, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",8628},{60,"Avenger's Greaves","","Kandrostrasz","Ahn'Qiraj","Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",8655},{60,"Avenger's Legguards","","Kandrostrasz","Ahn'Qiraj","Bring the Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",8629},{60,"Avenger's Pauldrons","","Andorgos","Ahn'Qiraj","Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Crystal Scarabs and 5 Gold Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",8630},{60,"Band of Unending Life","","Windcaller Yessendra","Silithus","Bring 1 Qiraji Magisterial Ring, 2 Alabaster Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",8700},{60,"Band of Vaulted Secrets","","Windcaller Yessendra","Silithus","Bring 1 Qiraji Magisterial Ring, 2 Azure Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",8699},{60,"Band of Veiled Shadows","","Windcaller Yessendra","Silithus","Bring 1 Qiraji Ceremonial Ring, 2 Onyx Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",8701},{60,"Blade of Eternal Justice","","Warden Haro","Silithus","Bring 1 Qiraji Spiked Hilt, 2  Amber Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",8711},{60,"Blade of Vaulted Secrets","","Warden Haro","Silithus","Bring 1 Qiraji Ornate Hilt, 2  Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",8707},{60,"C'Thun's Legacy","","Eye of C'Thun (an item)","","Take the Eye of C'Thun to Caelastrasz in the Temple of Ahn'Qiraj.",8801},{60,"Cape of Eternal Justice","","Keyl Swiftclaw","Silithus","Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",8695},{60,"Cloak of Unending Life","","Keyl Swiftclaw","Silithus","Bring 1 Qiraji Regal Drape, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",8692},{60,"Cloak of Veiled Shadows","","Keyl Swiftclaw","Silithus","Bring 1 Qiraji Martial Drape, 2 Azure Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",8693},{60,"Cloak of the Gathering Storm","