  [550] = { name = "Tempest Keep", raid = true, levels = {70,73,70}, picture = "TempestKeep", where = {"Netherstorm",73.9,63.7}, quests = {{70,"Harbinger of Doom","","A'dal","Shattrath City","You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss.  Return to A'dal at the Terrace of Light in Shattrath City after you have done so.",10882},{70,"How to Break Into the Arcatraz","","A'dal","Shattrath City","A'dal has tasked you with the recovery of the Top and Bottom Shards of the Arcatraz Key.  Return them to him, and he will fashion them into the Key to the Arcatraz for you.",10704},{70,"Kael'thas and the Verdant Sphere","","Verdant Sphere (an item)","","Take the Verdant Sphere to A'dal in Shattrath City.",11007},{70,"Ruse of the Ashtongue","","Akama","Shadowmoon Valley","Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl.  Return to Akama in Shadowmoon Valley once you've completed this task.",10946},{70,"Seer Udalo","","Akama","Shadowmoon Valley","Find Seer Udalo inside the Arcatraz in Tempest Keep.",10705},{70,"The Vials of Eternity","","Soridormi","Tanaris","Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.",13432},{70,"Wanted: A Warp Splinter Clipping","","Wind Trader Zhareem","Shattrath City","Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.",11384},{70,"Wanted: Arcatraz Sentinels","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.",11389},{70,"Wanted: Pathaleon's Projector","","Wind Trader Zhareem","Shattrath City","Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.",11386},{70,"Wanted: Sunseeker Channelers","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.",11385},{70,"Wanted: Tempest-Forge Destroyers","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.",11387},{70,"Wanted: The Scroll of Skyriss","","Wind Trader Zhareem","Shattrath City","Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.",11388}} },
