  [553] = { name = "Tempest Keep: The Botanica", raid = false, levels = {68,70,67}, picture = "TEMPESTKEEP", where = {"Netherstorm",71.8,54.8}, quests = {{70,"Capturing the Keystone","","Archmage Vargoth","Netherstorm","Venture into Tempest Keep's Botanica and retrieve the Keystone from Commander Sarannis. Bring it to Archmage Vargoth at the Violet Tower.",10257},{70,"How to Break Into the Arcatraz","","A'dal","Shattrath City","A'dal has tasked you with the recovery of the Top and Bottom Shards of the Arcatraz Key.  Return them to him, and he will fashion them into the Key to the Arcatraz for you.",10704},{70,"Master of Potions","","Lauranna Thar'well","Zangarmarsh","Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn.  In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.\n\n*WARNING!* You can only select one alchemy specialization.",10897},{70,"Wanted: Sunseeker Channelers","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.",11385}} },
  [554] = { name = "Tempest Keep: The Mechanar", raid = false, levels = {68,70,67}, picture = "TEMPESTKEEP", where = {"Netherstorm",70.6,69.8}, quests = {{70,"How to Break Into the Arcatraz","","A'dal","Shattrath City","A'dal has tasked you with the recovery of the Top and Bottom Shards of the Arcatraz Key.  Return them to him, and he will fashion them into the Key to the Arcatraz for you.",10704},{70,"Wanted: Tempest-Forge Destroyers","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.",11387}} },
  [555] = { name = "Auchindoun: Shadow Labyrinth", raid = false, levels = {68,70,67}, picture = "AUCHINDOUN", where = {"Terokkar Forest",39.6,73.8}, quests = {{69,"The Lexicon Demonica","","David Wayne","Terokkar Forest","Obtain the Lexicon Demonica from Grandmaster Vorpil and bring it to David Wayne at Wayne's Refuge.",10666},{70,"Entry Into Karazhan","","Khadgar","Shattrath City","Khadgar wants you to enter the Shadow Labyrinth at Auchindoun and retrieve the First Key Fragment from an Arcane Container hidden there.",9831},{70,"Into the Heart of the Labyrinth","","The Codex of Blood","","Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.",10095},{70,"The Book of Fel Names","","Altruis the Sufferer","Nagrand","Venture inside the Shadow Labyrinth in Auchindoun and obtain the Book of Fel Names from Blackheart the Inciter.  Return to Altruis in Nagrand once you've completed this task.",10649},{70,"Wanted: Malicious Instructors","","Nether-Stalker Mah'duun","Shattrath City","Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.",11376}} },
  [556] = { name = "Auchindoun: Sethekk Halls", raid = false, levels = {67,68,65}, picture = "AUCHINDOUN", where = {"Terokkar Forest",45.1,65.6}, quests = {{69,"Brother Against Brother","","Isfar","Terokkar Forest","Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk Halls when you've completed the rescue.",10097},{69,"Terokk's Legacy","","Isfar","Terokkar Forest","Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.",10098}} },
  [557] = { name = "Auchindoun: Mana-Tombs", raid = false, levels = {64,66,62}, picture = "AUCHINDOUN", where = {"Terokkar Forest",39.6,57.4}, quests = {{66,"Safety Is Job One","","Artificer Morphalius","Terokkar Forest","Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.",10216},{66,"Someone Else's Hard Work Pays Off","","Cryo-Engineer Sha'heen","","Escort Cryo-Engineer Sha'heen safely through the Mana-Tombs so that he can gather the ether held inside Shaffar's ether collectors.\n\nReport to Nexus-Prince Haramad located outside the Mana-Tombs at the Consortium encampment should you succeed.",10218},{66,"Undercutting the Competition","","Nexus-Prince Haramad","Terokkar Forest","Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.",10165},{70,"Nexus-Prince Shaffar's Personal Chamber","","Image of Commander Ameer","Blade's Edge Mountains","",10981},{70,"Stasis Chambers of the Mana-Tombs","","Image of Commander Ameer","Blade's Edge Mountains","The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.\n\nThis quest may only be completed on Heroic difficulty.",10977}} },
  [558] = { name = "Auchindoun: Auchenai Crypts", raid = false, levels = {65,67,63}, picture = "AUCHINDOUN", where = {"Terokkar Forest",34.2,65.6}, quests = {{67,"Everything Will Be Alright","","Greatfather Aldrimus","Terokkar Forest","Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.",10164},{68,"Auchindoun...","H","A'dal","Shattrath City","Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.",10167}} },
