  [574] = { name = "Utgarde Keep", raid = false, levels = {69,72,68}, picture = "UTGARDE", where = {"Howling Fjord",57.2,46.1}, quests = {{71,"A Score to Settle","H","High Executor Anselm","Howling Fjord","High Executor Anselm wants you to to go into Utgarde and slay Prince Keleseth.",11272},{71,"Disarmament","A","Defender Mordun","Howling Fjord","Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons",13205},{71,"Disarmament","H","Dark Ranger Marrah","Utgarde Keep","Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to High Executor Anselm in Vengeance Landing.",13206},{71,"Ingvar Must Die!","H","Dark Ranger Marrah","Utgarde Keep","Dark Ranger Marrah has asked you to kill Ingvar the Plunderer in Utgarde Keep, then bring his head to High Executor Anselm at Vengeance Landing.",11262},{71,"Into Utgarde!","A","Defender Mordun","Howling Fjord","Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.\n\nYou are then to bring his head to Vice Admiral Keller.",11252}} },
